window.AUTH=window.AUTH||{};window.AUTH["20-322"]={"d":"20-322","id":"2021/20-322","n":"Garland v. Gonzalez","briefs":[{"k":"petitioner","label":"Brief of petitioners Merrick B. Garland, Attorney General, et al.","date":"2021-10-14","url":"https://www.supremecourt.gov/DocketPDF/20/20-322/196427/20211014164654895_20-322tsUnitedStates.pdf","side":"pet","n":91},{"k":"respondent","label":"Brief of respondents Esteban A. Gonzalez, et al.","date":"2021-11-22","url":"https://www.supremecourt.gov/DocketPDF/20/20-322/200869/20211122132257024_20-322%20Garland%20v%20Gonzalez%20Brief%20on%20the%20Merits%20for%20Respondents.pdf","side":"res","n":135},{"k":"reply","label":"Reply of petitioners Merrick B. Garland, Attorney General, et al.","date":"2021-12-22","url":"https://www.supremecourt.gov/DocketPDF/20/20-322/206240/20211222180822148_No.%2020-322%20Garland%20et%20al.%20v.%20Aleman%20Gonzalez%20et%20al.%20Final.pdf","side":"pet","n":51}],"opinion":"https://www.supremecourt.gov/opinions/21pdf/596us2r39_7l48.pdf","tr":true,"items":[{"t":"case","label":"Aberdeen & Rockfish Railroad v. Students Challenging Regulatory Agency Procedures (SCRAP)","cite":"422 U.S. 289","y":1975,"id":"1974/73-1966","sc":1,"sum":"In December 1971, the Nation's railroads, citing sharply increasing costs and decreasing or negative profits, collectively proposed to file tariffs increasing their freight rates by a temporary surcharge across the board. The Interstate Commerce Commission (ICC), in the ensuing general revenue proceeding, finding that the railroads had a critical and immediate need for revenue, declined to exercise its power to …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18"}},{"t":"case","label":"Abney v. United States","cite":"431 U.S. 651","y":1977,"id":"1976/75-6521","sc":1,"sum":"Petitioners and others were charged in a single-count indictment with conspiracy and an attempt to obstruct interstate commerce by means of extortion, in violation of the Hobbs Act. Petitioners challenged the indictment as duplicitous, contending that its single count improperly charged both a conspiracy and an attempt to violate the Hobbs Act. The District Court refused to dismiss the indictment but required the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"45"}},{"t":"case","label":"Ali v. Ashcroft","cite":"346 F.3d 873","y":2003,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/346/873/","by":{"0":"16"}},{"t":"case","label":"American Express Co. v. Italian Colors Restaurant","cite":"570 U.S. 228","y":2013,"id":"2012/12-133","sc":1,"sum":"The Court held that a clause prohibiting class action suits was enforceable even though it would cause costly arbitration.","sumSrc":"Oyez","by":{"0":"32"}},{"t":"case","label":"Barton v. Barr","cite":"140 S. Ct. 1442","y":2020,"id":"2019/18-725","sc":1,"op":1,"sum":"The Court held that in determining eligibility for cancellation of removal of a lawful permanent resident who commits a serious crime, an offense listed in 8 U.S.C. § 1182(a)(2) committed during the initial seven years of residence need not be one of the offenses of removal.","sumSrc":"Oyez","by":{"0":"2","1":"59"}},{"t":"case","label":"Borden v. United States","cite":"141 S. Ct. 1817","y":2021,"id":"2020/19-5410","sc":1,"sum":"The decision of the Sixth Circuit—holding that an offense with a mental state of recklessness may qualify as a “violent felony” under the Armed Career Criminal Act’s elements clause, 18 U. S. C. §924(e)(2)(B)(i)—is reversed, and the case is remanded.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"36"}},{"t":"case","label":"Burlington Northern & Santa Fe Railway Co. v. White","cite":"548 U.S. 53","y":2006,"id":"2005/05-259","sc":1,"sum":"In a decision authored by Justice Stephen Breyer and joined by Chief Justice Roberts and six other justices, the Court held that in order to prevail on a claim of retaliatory discrimination, \"a plaintiff must show that a reasonable employee would have found the challenged action materially adverse, which in this context means it well might have dissuaded a reasonable worker from making or supporting a charge of discrimination.\" (internal citations omitted) Justice Samuel Alito wrote separately, agreeing with the result but arguing that the test adopted by the other members of the Court would eventually prove problematic.","sumSrc":"Oyez","by":{"0":"29"}},{"t":"case","label":"Califano v. Sanders","cite":"430 U.S. 99","y":1977,"id":"1976/75-1443","sc":1,"sum":"1. Section 10 of the Administrative Procedure Act (APA), providing generally for judicial review of actions of federal administrative agencies by persons aggrieved by such actions, does not afford an implied grant to district courts of subject-matter jurisdiction to review a decision of the Secretary of Health, Education, and Welfare not to reopen a previously adjudicated claim for social security benefits. An …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21"}},{"t":"case","label":"Califano v. Yamasaki","cite":"442 U.S. 682","y":1979,"id":"1978/77-1511","sc":1,"op":4,"sum":"Section 204 (a) (1) of the Social Security Act (Act) authorizes the Secretary of the Department of Health, Education, and Welfare to recoup erroneous overpayments made to a beneficiary under the old-age, survivors', or disability insurance programs by decreasing future payments to which the overpaid person is entitled. However, § 204 (b) commands that \"there shall be no adjustment of payments to, or recovery by the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"30","1":"42, 58","2":"7, 10"}},{"t":"case","label":"Carlson v. Landon","cite":"342 U.S. 524","y":1952,"id":"scdb/1951-054","sc":1,"sum":"1. Under § 20 (a) of the Immigration Act, as amended by § 23 of the Internal Security Act, the Attorney General may, in his discretion, hold in custody without bail, pending determination as to their deportability, aliens who are members of the Communist Party of the United States, when there is reasonable cause to believe that their release on bail would endanger the safety and welfare of the United States.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"42","1":"35, 36","2":"20"}},{"t":"case","label":"DHS v. Thuraissigiam","cite":"140 S. Ct. 1959","y":2020,"id":"2019/19-161","sc":1,"sum":"The Court held that 8 U.S.C. § 1252(e)(2) as applied to the respondent Thuraissigiam does not violate the Suspension Clause of the Constitution.","sumSrc":"Oyez","by":{"0":"24"}},{"t":"case","label":"Demore v. Kim","cite":"538 U.S. 510","y":2003,"id":"2002/01-1491","sc":1,"op":1,"ar":3,"sum":"Explaining that immigration offcials “can detain, transfer, and isolate aliens away from their lawyers, witnesses, and evidence”.","sumSrc":"opinion","by":{"0":"42","1":"20, 34, 35","2":"4, 19, 20"}},{"t":"case","label":"Diouf v. Napolitano","cite":"634 F.3d 1081","y":2011,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/634/1081/","by":{"0":"passim","1":"12, 45"}},{"t":"case","label":"Direct Marketing Ass’n v. Brohl","cite":"575 U.S. 1","y":2015,"id":"2014/13-1032","sc":1,"op":2,"sum":"The Court held that the Tax Injunction Act does not prevent federal court review of state tax laws, unless such review could restrict the ability of the state to assess or collect its own taxes.","sumSrc":"Oyez","by":{"0":"18"}},{"t":"case","label":"EEOC v. Abercrombie & Fitch Stores, Inc.","cite":"575 U.S. 768","y":2015,"id":"2014/14-86","sc":1,"sum":"The Court held that an employer may be held liable under Title VII of the Civil Rights Act if an applicant can show that her need for an accommodation was a motivating factor in the employer’s decision not to hire her.","sumSrc":"Oyez","by":{"0":"35"}},{"t":"case","label":"Elgin v. Department of the Treasury","cite":"567 U.S. 1","y":2012,"id":"2011/11-45","sc":1,"sum":"The Court held that the Civil Service Reform Act precludes federal courts' jurisdiction in cases where federal employees seek equitable relief.","sumSrc":"Oyez","by":{"0":"21"}},{"t":"case","label":"Fernandez-Vargas v. Gonzales","cite":"548 U.S. 30","y":2006,"id":"2005/04-1376","sc":1,"sum":"The Court ruled that the reinstatement statute does apply to illegal aliens who re-entered the U.S. before the effective date of the statute, and that the application to such aliens was not impermissibly retroactive.","sumSrc":"Oyez","by":{"0":"7"}},{"t":"case","label":"Goldberg v. Kelly","cite":"397 U.S. 254","y":1970,"id":"1969/62","sc":1,"sum":"In a 5-to-3 decision, the Court held that states must afford public aid recipients a pre-termination evidentiary hearing before discontinuing their aid.","sumSrc":"Oyez","by":{"0":"45","1":"42","2":"23"}},{"t":"case","label":"Guerrero-Sanchez v. Warden York County Prison","cite":"905 F.3d 208","y":2018,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/905/208/","by":{"0":"passim"}},{"t":"case","label":"Hamama v. Adducci","cite":"912 F.3d 869","y":2018,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/912/869/","op":1,"by":{"0":"23, 35"}},{"t":"case","label":"Hertz Corp. v. Friend","cite":"559 U.S. 77","y":2010,"id":"2009/08-1107","sc":1,"sum":"The Court held that the court system cannot disregard the location of a corporation's principal place of business in a multi-state lawsuit.","sumSrc":"Oyez","by":{"0":"22"}},{"t":"case","label":"Hewitt v. Helms","cite":"459 U.S. 460","y":1983,"id":"1982/81-638","sc":1,"sum":"Following a riot in the Pennsylvania State Prison where he was an inmate, respondent was removed from his cell and the general prison population and confined to administrative segregation within the prison pending an investigation into his role in the riot. The next day respondent received notice of a misconduct charge against him. Five days after his transfer to administrative segregation a Hearing Committee …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"45"}},{"t":"case","label":"Hibbs v. Winn","cite":"542 U.S. 88","y":2004,"id":"2003/02-1809","sc":1,"sum":"In a 5-to-4 decision written by Justice Ruth Bader Ginsburg, the Court held that the intention of the Tax Injunction Act (TIA) was to prevent taxpayers from trying to avoid their state taxes through federal litigation. TIA was not intended, however, to prevent all federal interference with state taxation.","sumSrc":"Oyez","by":{"0":"18"}},{"t":"case","label":"Jennings v. Rodriguez","cite":"138 S. Ct. 830","y":2018,"id":"2017/15-1204","sc":1,"op":2,"ar":5,"sum":"The Court held that non-citizens who are subject to mandatory detention under the Immigration and Nationality Act are not entitled to periodic bond hearings. with the possibility of release if they are detained for longer than six months.","sumSrc":"Oyez","by":{"0":"passim","1":"passim","2":"7, 8, 9, 14"}},{"t":"case","label":"Johnson v. Guzman Chavez","cite":"141 S. Ct. 2271","y":2021,"id":"2020/19-897","sc":1,"op":2,"ar":1,"sum":"The detention of an alien ordered removed from the United States who reenters without authorization is governed by 8 U. S. C. §1231.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"14, 36, 38","1":"6, 20, 36"}},{"t":"case","label":"Knight v. Commissioner","cite":"552 U.S. 181","y":2008,"id":"2007/06-1286","sc":1,"sum":"Roberts reasoned that the tax statute at issue required a court to decide whether an individual customarily would spend money on the type of service at issue; if so, the expense would not be fully deductible by a trust. The case was remanded for further proceedings.","sumSrc":"Oyez","by":{"0":"31"}},{"t":"case","label":"Lamar, Archer & Cofrin, LLP v. Appling","cite":"138 S. Ct. 1752","y":2018,"id":"2017/16-1215","sc":1,"sum":"The Court decided that a statement regarding a specific asset can be a “statement respecting the debtor’s . . . financial condition” under section 523(a)(2)(B) of the Bankruptcy Code.","sumSrc":"Oyez","by":{"0":"29"}},{"t":"case","label":"Lomax v. Ortiz-Marquez","cite":"140 S. Ct. 1721","y":2020,"id":"2019/18-8369","sc":1,"sum":"The Court held that a dismissal without prejudice for failure to state a claim counts as a strike under the Prison Litigation Reform Act, 28 U.S.C. § 1915(g), which bars inmates from filing or appealing a federal civil action without paying the associated fees if they have filed three or more cases or appeals that were dismissed because the lawsuits were frivolous or malicious or did not properly state a legal claim for relief.","sumSrc":"Oyez","by":{"0":"19"}},{"t":"case","label":"Martinez v. LaRose","cite":"968 F.3d 555","y":2020,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/968/555/","by":{"0":"35"}},{"t":"case","label":"Mohamad v. Palestinian Authority","cite":"566 U.S. 449","y":2012,"id":"2011/11-88","sc":1,"sum":"The Court held that the word \"individual\" in the Torture Victim Protection Act means a natural person and does not impose any liability against organizations.","sumSrc":"Oyez","by":{"0":"30"}},{"t":"case","label":"Nielsen v. Preap","cite":"139 S. Ct. 954","y":2019,"id":"2018/16-1363","sc":1,"op":1,"sum":"The Ninth Circuit’s judgments—that respondents, who are deportable for certain specified crimes, are not subject to 8 U. S. C. §1226(c)(2)’s mandatory-detention requirement because they were not arrested by immigration officials as soon as they were released from jail—are reversed, and the cases are remanded.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"3, 12, 16, 19, 22, 32","2":"5"}},{"t":"case","label":"Niz-Chavez v. Garland","cite":"141 S. Ct. 1474","y":2021,"id":"2020/19-863","sc":1,"sum":"A notice to appear sufficient to trigger the Illegal Immigration Reform and Immigrant Responsibility Act of 1996’s stop-time rule is a single document containing all the information about an individual’s removal hearing specified in 8 U. S. C. §1229(a)(1).","sumSrc":"Holding (supremecourt.gov)","by":{"0":"28"}},{"t":"case","label":"Nken v. Holder","cite":"556 U.S. 418","y":2009,"id":"2008/08-681","sc":1,"op":6,"sum":"The Court held that a court of appeals' decision to stay an alien's removal pending consideration of the alien's petition for review is governed by the 4-factor traditional test.","sumSrc":"Oyez","by":{"0":"13, 17, 23, 24, 26","1":"6, 13, 57"}},{"t":"case","label":"Padilla v. ICE","cite":"953 F.3d 1134","y":2020,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/953/1134/","by":{"0":"13, 25, 26, 27, 29, 31"}},{"t":"case","label":"Pavelic & LeFlore v. Marvel Entertainment Group","cite":"493 U.S. 120","y":1989,"id":"1989/88-791","sc":1,"sum":"When read in the context of all of Rule ll's signature provisions, the phrase \"person who signed\" connotes the individual signer mentioned at the outset of the Rule and authorizes a court to impose a sanction only against that individual. That is so even when the individual explicitly signs on behalfof the firm, since it is only the signature \"in the attorney's individual name\" which complies with the Rule's …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"37"}},{"t":"case","label":"Phillips v. United States","cite":"312 U.S. 246","y":1941,"id":"scdb/1940-167","sc":1,"by":{"0":"20"}},{"t":"case","label":"Reno v. American-Arab Anti-Discrimination Committee (AADC)","cite":"525 U.S. 471","y":1999,"id":"1998/97-1252","sc":1,"op":2,"sum":"Announced by Justice Antonin Scalia, the Court ruled that the IIRIRA deprives federal courts of jurisdiction over the selective-enforcement claim.","sumSrc":"Oyez","by":{"0":"13, 23, 24, 25, 26, 27","1":"56","2":"7"}},{"t":"case","label":"Reno v. Flores","cite":"507 U.S. 292","y":1993,"id":"1992/91-905","sc":1,"sum":"Respondents are a class of alien juveniles arrested by the Immigration and Naturalization Service (INS) on suspicion of being deportable, and then detained pending deportation hearings pursuant to a regulation, promulgated in 1988 and codified at 8 CFR §242.24, which provides for the release of detained minors only to their parents, close relatives, or legal guardians, except in unusual and compelling circumstances. …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"41, 46"}},{"t":"case","label":"Rodriguez v. Hayes","cite":"591 F.3d 1105","y":2010,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/591/1105/","op":1,"by":{"0":"passim","2":"5"}},{"t":"case","label":"Rotkiske v. Klemm","cite":"140 S. Ct. 355","y":2019,"id":"2019/18-328","sc":1,"sum":"The Court held that the one-year statute of limitations under the Fair Debt Collection Practices Act begins when the violation occurred, not when the violation was discovered.","sumSrc":"Oyez","by":{"0":"35"}},{"t":"case","label":"Schweiker v. McClure","cite":"456 U.S. 188","y":1982,"id":"1981/81-212","sc":1,"sum":"The hearing procedures in question do not violate due process requirements.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"44","1":"40, 41"}},{"t":"case","label":"Sisson v. Ruby","cite":"497 U.S. 358","y":1990,"id":"1989/88-2041","sc":1,"sum":"The Court held that the district court has maritime jurisdiction when the incident in question represents a potential hazard to maritime commerce and bears a substantial relationship to maritime activity.","sumSrc":"Oyez","by":{"0":"21"}},{"t":"case","label":"Vermont Yankee Nuclear Power Corp. v. Natural Resources Defense Council, Inc.","cite":"435 U.S. 519","y":1978,"id":"1977/76-419","sc":1,"ar":3,"sum":"In No. 76-419, after extensive hearings before the Atomic Safety and Licensing Board (Licensing Board) and over respondents' objections, the Atomic Energy Commission (AEC) granted petitioner Vermont Yankee Nuclear Power Corp. a license to operate a nuclear power plant, and this ruling was affirmed by the Atomic Safety and Licensing Appeal Board (Appeal Board). Subsequently, the AEC, specifically referring to the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"40","2":"15"}},{"t":"case","label":"Wal-Mart Stores, Inc. v. Dukes","cite":"564 U.S. 338","y":2011,"id":"2010/10-277","sc":1,"op":1,"sum":"The Court held that the small group who initiated a lawsuit could not represent all of Wal-Mart's female employees, and therefore could not bring a class action lawsuit against Wal-Mart.","sumSrc":"Oyez","by":{"0":"28","2":"12"}},{"t":"case","label":"Withrow v. Larkin","cite":"421 U.S. 35","y":1975,"id":"1974/73-1573","sc":1,"sum":"Wisconsin statutes prohibit various acts of professional misconduct by physicians and empower a State Examining Board to warn and reprimand physicians, to temporarily suspend licenses, and to institute criminal action or action to revoke a license. When the Board notified appellee licensed physician that a closed investigative hearing, which appellee and his attorney could attend, would be held to determine whether …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"44","1":"40, 41","2":"22"}},{"t":"case","label":"Wong Wing v. United States","cite":"163 U.S. 228","y":1896,"id":"1850-1900/163us228","sc":1,"sum":"Consequently, the imprisonment provisions of the Act are void.","sumSrc":"Oyez","by":{"0":"42"}},{"t":"case","label":"Wong Yang Sung v. McGrath","cite":"339 U.S. 33","y":1950,"id":"scdb/1949-048","sc":1,"sum":"This was contrary to the purpose of the Administrative Procedure Act to ameliorate the evils resulting from a combination of the prosecuting and adjudicating functions in administrative proceedings.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21"}},{"t":"case","label":"Zadvydas v. Davis","cite":"533 U.S. 678","y":2001,"id":"2000/99-7791","sc":1,"ar":13,"sum":"The Court held that \"the statute, read in light of the Constitution's demands, limits an alien's post-removal-period detention to a period reasonably necessary to bring about that alien's removal from the United States\" and \"does not permit indefinite detention.\" \"Based on our conclusion that indefinite detention of aliens in the former category would raise serious constitutional concerns, we construe the statute to contain an implicit 'reasonable time' limitation, the application of which is subject to federal court review,\" wrote Justice Breyer.","sumSrc":"Oyez","by":{"0":"4, 14, 43, 46, 47, 48","1":"passim","2":"18, 19"}},{"t":"const","label":"Amendment V","clauses":[["due-process-5","Due Process Clause (Fifth Amendment)"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"0":"7, 41, 42, 43, 44, 46, 48","1":"29, 35","2":"19, 20, 21, 22"}},{"t":"law","label":"Pub. L. No. 104-208","url":"https://www.govinfo.gov/link/plaw/104/public/208","by":{"0":"13, 23","2":"7"}},{"t":"usc","label":"8 U.S.C. § 1101","url":"https://www.law.cornell.edu/uscode/text/8/1101","subs":["(a)(3)"],"stext":{"head":"§1101. Definitions","paras":[[0,"(a) As used in this chapter—"],[0,"(1) The term \"administrator\" means the official designated by the Secretary of State pursuant to section 1104(b) of this title."],[0,"(2) The term \"advocates\" includes, but is not limited to, advises, recommends, furthers by overt act, and admits belief in."],[0,"(3) The term \"alien\" means any person not a citizen or national of the United States."],[0,"(4) The term \"application for admission\" has reference to the application for admission into the United States and not to the application for the issuance of an immigrant or nonimmigrant visa."],[0,"(5) The term \"Attorney General\" means the Attorney General of the United States."],[0,"(6) The term \"border crossing identification card\" means a document of identity bearing that designation issued to an alien who is lawfully admitted for permanent residence, or to an alien who is a resident in foreign contiguous territory, by a consular officer or an immigration officer for the purpose of crossing over the borders between the United States and foreign contiguous territory in accordance with such conditions for its issuance and use as may be prescribed by regulations. Such regulations shall provide that (A) each such document include a biometric identifier (such as the fingerprint or handprint of the alien) that is machine readable and (B) an alien presenting a border crossing identification card is not permitted to cross over the border into the United States unless the biometric identifier contained on the card matches the appropriate biometric characteristic of the alien."],[0,"(7) The term \"clerk of court\" means a clerk of a naturalization court."],[0,"(8) The terms \"Commissioner\" and \"Deputy Commissioner\" mean the Commissioner of Immigration and Naturalization and a Deputy Commissioner of Immigration and Naturalization, respectively."],[0,"(9) The term \"consular officer\" means any consular, diplomatic, or other officer or employee of the United States designated under regulations prescribed under authority contained in this chapter, for the purpose of issuing immigrant or nonimmigrant visas or, when used in subchapter III, for the purpose of adjudicating nationality."],[0,"(10) The term \"crewman\" means a person serving in any capacity on board a vessel or aircraft."],[0,"(11) The term \"diplomatic visa\" means a nonimmigrant visa bearing that title and issued to a nonimmigrant in accordance with such regulations as the Secretary of State may prescribe."],[0,"(12) The term \"doctrine\" includes, but is not limited to, policies, practices, purposes, aims, or procedures."],[0,"(13)(A) The terms \"admission\" and \"admitted\" mean, with respect to an alien, the lawful entry of the alien into the United States after inspection and authorization by an immigration officer."],[0,"(B) An alien who is paroled under section 1182(d)(5) of this title or permitted to land temporarily as an alien crewman shall not be considered to have been admitted."],[0,"(C) An alien lawfully admitted for permanent residence in the United States shall not be regarded as seeking an admission into the United States for purposes of the immigration laws unless the alien—"],[1,"(i) has abandoned or relinquished that status,"],[1,"(ii) has been absent from the United States for a continuous period in excess of 180 days,"],[1,"(iii) has engaged in illegal activity after having departed the United States,"],[1,"(iv) has departed from the United States while under legal process seeking removal of the alien from the United States, including removal proceedings under this chapter and extradition proceedings,"],[1,"(v) has committed an offense identified in section 1182(a)(2) of this title, unless since such offense the alien has been granted relief under section 1182(h) or 1229b(a) of this title, or"],[1,"(vi) is attempting to enter at a time or place other than as designated by immigration officers or has not been admitted to the United States after inspection and authorization by an immigration officer."],[0,"(14) The term \"foreign state\" includes outlying possessions of a foreign state, but self-governing dominions or territories under mandate or trusteeship shall be regarded as separate foreign states."],[0,"(15) The term \"immigrant\" means every alien except an alien who is within one of the following classes of nonimmigrant aliens—"],[1,"(A)(i) an ambassador, public minister, or career diplomatic or consular officer who has been accredited by a foreign government, recognized de jure by the United States and who is accepted by the President or by the Secretary of State, and the members of the alien's immediate family;"],[1,"(ii) upon a basis of reciprocity, other officials and employees who have been accredited by a foreign government recognized de jure by the United States, who are accepted by the Secretary of State, and the members of their immediate families; and"],[1,"(iii) upon a basis of reciprocity, attendants, servants, personal employees, and members of their immediate families, of the officials and employees who have a nonimmigrant status under (i) and (ii) above;"],[1,"(B) an alien (other than one coming for the purpose of study or of performing skilled or unskilled labor or as a representative of foreign press, radio, film, or other foreign information media coming to engage in such vocation) having a residence in a foreign country which he has no intention of abandoning and who is visiting the United States temporarily for business or temporarily for pleasure;"],[1,"(C)(i) an alien in immediate and continuous transit through the United States, for a period not to exceed 29 days;"],[1,"(ii) an alien who qualifies as a person entitled to pass in transit to and from the United Nations Headquarters District (as defined in section 4309a(e) of title 22) and foreign countries, under the provisions of paragraphs (3), (4), and (5) of section 11 of the Agreement regarding the Headquarters of the United Nations, done at Lake Success June 26, 1947 (61 Stat. 758); or"],[1,"(iii) an alien passing in transit through the United States to board a vessel on which the alien will perform, or to disembark from a vessel on which the alien performed, ship-to-ship liquid cargo transfer operations to or from another vessel engaged in foreign trade, for a period not to exceed 180 days;"],[1,"(D)(i) an alien crewman serving in good faith as such in a capacity required for normal operation and service on board a vessel, as defined in section 1288(a) of this title (other than a fishing vessel having its home port or an operating base in the United States), or aircraft, who intends to land temporarily and solely in pursuit of his calling as a crewman and to depart from the United States with the vessel or aircraft on which he arrived or some other vessel or aircraft;"],[1,"(ii) an alien crewman serving in good faith as such in any capacity required for normal operations and service aboard a fishing vessel having its home port or an operating base in the United States who intends to land temporarily in Guam or the Commonwealth of the Northern Mariana Islands and solely in pursuit of his calling as a crewman and to depart from Guam or the Commonwealth of the Northern Mariana Islands with the vessel on which he arrived; or"],[1,"(iii) an alien crewman performing ship-to-ship liquid cargo transfer operations to or from another vessel engaged in foreign trade, who intends to land temporarily solely in pursuit of the alien's responsibilities as a crewman and to depart from the United States on the vessel on which the alien arrived or on another vessel or aircraft, for a period not to exceed 180 days;"],[1,"(E) an alien entitled to enter the United States under and in pursuance of the provisions of a treaty of commerce and navigation between the United States and the foreign state of which the alien is a national (or, in the case of an alien who acquired the relevant nationality through a financial investment and who has not previously been granted status under this subparagraph, the foreign state of which the alien is a national and in which the alien has been domiciled for a continuous period of not less than 3 years at any point before applying for a nonimmigrant visa under this subparagraph), and the spouse and children of any such alien if accompanying or following to join such alien; (i) solely to carry on substantial trade, including trade in services or trade in technology, principally between the United States and the foreign state of which the alien is a national; (ii) solely to develop and direct the operations of an enterprise in which the alien has invested, or of an enterprise in which the alien is actively in the process of investing, a substantial amount of capital; or (iii) solely to perform services in a specialty occupation in the United States if the alien is a national of the Commonwealth of Australia and with respect to whom the Secretary of Labor determines and certifies to the Secretary of Homeland Security and the Secretary of State that the intending employer has filed with the Secretary of Labor an attestation under section 1182(t)(1) of this title;"],[1,"(F)(i) an alien having a residence in a foreign country which he has no intention of abandoning, who is a bona fide student qualified to pursue a full course of study and who seeks to enter the United States temporarily and solely for the purpose of pursuing such a course of study consistent with section 1184(l) 1 of this title at an established college, university, seminary, conservatory, academic high school, elementary school, or other academic institution or in an accredited language training program in the United States, particularly designated by him and approved by the Attorney General after consultation with the Secretary of Education, which institution or place of study shall have agreed to report to the Attorney General the termination of attendance of each nonimmigrant student, and if any such institution of learning or place of study fails to make reports promptly the approval shall be withdrawn, (ii) the alien spouse and minor children of any alien described in clause (i) if accompanying or following to join such an alien, and (iii) an alien who is a national of Canada or Mexico, who maintains actual residence and place of abode in the country of nationality, who is described in clause (i) except that the alien's qualifications for and actual course of study may be full or part-time, and who commutes to the United States institution or place of study from Canada or Mexico;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1101?type=usc&year=mostrecent&link-type=html"},"head":"§1101. Definitions","tname":"Aliens and Nationality","by":{"0":"3, 2","2":"17"}},{"t":"usc","label":"8 U.S.C. § 1103","url":"https://www.law.cornell.edu/uscode/text/8/1103","subs":["(a)(1)","(g)(1)","(a)(6)"],"stext":{"head":"§1103. Powers and duties of the Secretary, the Under Secretary, and the Attorney General","paras":[[0,"(a) Secretary of Homeland Security"],[0,"(1) The Secretary of Homeland Security shall be charged with the administration and enforcement of this chapter and all other laws relating to the immigration and naturalization of aliens, except insofar as this chapter or such laws relate to the powers, functions, and duties conferred upon the President, Attorney General, the Secretary of State, the officers of the Department of State, or diplomatic or consular officers: Provided, however, That determination and ruling by the Attorney General with respect to all questions of law shall be controlling."],[0,"(2) He shall have control, direction, and supervision of all employees and of all the files and records of the Service."],[0,"(3) He shall establish such regulations; prescribe such forms of bond, reports, entries, and other papers; issue such instructions; and perform such other acts as he deems necessary for carrying out his authority under the provisions of this chapter."],[0,"(4) He may require or authorize any employee of the Service or the Department of Justice to perform or exercise any of the powers, privileges, or duties conferred or imposed by this chapter or regulations issued thereunder upon any other employee of the Service."],[0,"(5) He shall have the power and duty to control and guard the boundaries and borders of the United States against the illegal entry of aliens and shall, in his discretion, appoint for that purpose such number of employees of the Service as to him shall appear necessary and proper."],[0,"(6) He is authorized to confer or impose upon any employee of the United States, with the consent of the head of the Department or other independent establishment under whose jurisdiction the employee is serving, any of the powers, privileges, or duties conferred or imposed by this chapter or regulations issued thereunder upon officers or employees of the Service."],[0,"(7) He may, with the concurrence of the Secretary of State, establish offices of the Service in foreign countries; and, after consultation with the Secretary of State, he may, whenever in his judgment such action may be necessary to accomplish the purposes of this chapter, detail employees of the Service for duty in foreign countries."],[0,"(8) After consultation with the Secretary of State, the Attorney General may authorize officers of a foreign country to be stationed at preclearance facilities in the United States for the purpose of ensuring that persons traveling from or through the United States to that foreign country comply with that country's immigration and related laws."],[0,"(9) Those officers may exercise such authority and perform such duties as United States immigration officers are authorized to exercise and perform in that foreign country under reciprocal agreement, and they shall enjoy such reasonable privileges and immunities necessary for the performance of their duties as the government of their country extends to United States immigration officers."],[0,"(10) In the event the Attorney General determines that an actual or imminent mass influx of aliens arriving off the coast of the United States, or near a land border, presents urgent circumstances requiring an immediate Federal response, the Attorney General may authorize any State or local law enforcement officer, with the consent of the head of the department, agency, or establishment under whose jurisdiction the individual is serving, to perform or exercise any of the powers, privileges, or duties conferred or imposed by this chapter or regulations issued thereunder upon officers or employees of the Service."],[0,"(11) The Attorney General, in support of persons in administrative detention in non-Federal institutions, is authorized—"],[1,"(A) to make payments from funds appropriated for the administration and enforcement of the laws relating to immigration, naturalization, and alien registration for necessary clothing, medical care, necessary guard hire, and the housing, care, and security of persons detained by the Service pursuant to Federal law under an agreement with a State or political subdivision of a State; and"],[1,"(B) to enter into a cooperative agreement with any State, territory, or political subdivision thereof, for the necessary construction, physical renovation, acquisition of equipment, supplies or materials required to establish acceptable conditions of confinement and detention services in any State or unit of local government which agrees to provide guaranteed bed space for persons detained by the Service."],[0,"(b) Land acquisition authority"],[0,"(1) The Attorney General may contract for or buy any interest in land, including temporary use rights, adjacent to or in the vicinity of an international land border when the Attorney General deems the land essential to control and guard the boundaries and borders of the United States against any violation of this chapter."],[0,"(2) The Attorney General may contract for or buy any interest in land identified pursuant to paragraph (1) as soon as the lawful owner of that interest fixes a price for it and the Attorney General considers that price to be reasonable."],[0,"(3) When the Attorney General and the lawful owner of an interest identified pursuant to paragraph (1) are unable to agree upon a reasonable price, the Attorney General may commence condemnation proceedings pursuant to section 3113 of title 40."],[0,"(4) The Attorney General may accept for the United States a gift of any interest in land identified pursuant to paragraph (1)."],[0,"(c) Commissioner; appointment"],[0,"The Commissioner shall be a citizen of the United States and shall be appointed by the President, by and with the advice and consent of the Senate. He shall be charged with any and all responsibilities and authority in the administration of the Service and of this chapter which are conferred upon the Attorney General as may be delegated to him by the Attorney General or which may be prescribed by the Attorney General. The Commissioner may enter into cooperative agreements with State and local law enforcement agencies for the purpose of assisting in the enforcement of the immigration laws."],[0,"(d) Statistical information system"],[0,"(1) The Commissioner, in consultation with interested academicians, government agencies, and other parties, shall provide for a system for collection and dissemination, to Congress and the public, of information (not in individually identifiable form) useful in evaluating the social, economic, environmental, and demographic impact of immigration laws."],[0,"(2) Such information shall include information on the alien population in the United States, on the rates of naturalization and emigration of resident aliens, on aliens who have been admitted, paroled, or granted asylum, on nonimmigrants in the United States (by occupation, basis for admission, and duration of stay), on aliens who have not been admitted or have been removed from the United States, on the number of applications filed and granted for cancellation of removal, and on the number of aliens estimated to be present unlawfully in the United States in each fiscal year."],[0,"(3) Such system shall provide for the collection and dissemination of such information not less often than annually."],[0,"(e) Annual report"],[0,"(1) The Commissioner shall submit to Congress annually a report which contains a summary of the information collected under subsection (d) and an analysis of trends in immigration and naturalization."],[0,"(2) Each annual report shall include information on the number, and rate of denial administratively, of applications for naturalization, for each district office of the Service and by national origin group."],[0,"(f) Minimum number of agents in States"],[0,"The Attorney General shall allocate to each State not fewer than 10 full-time active duty agents of the Immigration and Naturalization Service to carry out the functions of the Service, in order to ensure the effective enforcement of this chapter."],[0,"(g) Attorney General"],[0,"(1) In general"],[1,"The Attorney General shall have such authorities and functions under this chapter and all other laws relating to the immigration and naturalization of aliens as were exercised by the Executive Office for Immigration Review, or by the Attorney General with respect to the Executive Office for Immigration Review, on the day before the effective date of the Immigration Reform, Accountability and Security Enhancement Act of 2002."],[0,"(2) Powers"],[1,"The Attorney General shall establish such regulations, prescribe such forms of bond, reports, entries, and other papers, issue such instructions, review such administrative determinations in immigration proceedings, delegate such authority, and perform such other acts as the Attorney General determines to be necessary for carrying out this section."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1103?type=usc&year=mostrecent&link-type=html"},"head":"§1103. Powers and duties of the Secretary, the Under Secretary, and the Attorney General","tname":"Aliens and Nationality","by":{"0":"36","1":"26","2":"17, 17"}},{"t":"usc","label":"8 U.S.C. § 1225","url":"https://www.law.cornell.edu/uscode/text/8/1225","subs":["(b)(1)(B)(iii)(III)","(b)(1)","(b)(2)"],"stext":{"head":"§1225. Inspection by immigration officers; expedited removal of inadmissible arriving aliens; referral for hearing","paras":[[0,"(a) Inspection"],[0,"(1) Aliens treated as applicants for admission"],[1,"An alien present in the United States who has not been admitted or who arrives in the United States (whether or not at a designated port of arrival and including an alien who is brought to the United States after having been interdicted in international or United States waters) shall be deemed for purposes of this chapter an applicant for admission."],[0,"(2) Stowaways"],[1,"An arriving alien who is a stowaway is not eligible to apply for admission or to be admitted and shall be ordered removed upon inspection by an immigration officer. Upon such inspection if the alien indicates an intention to apply for asylum under section 1158 of this title or a fear of persecution, the officer shall refer the alien for an interview under subsection (b)(1)(B). A stowaway may apply for asylum only if the stowaway is found to have a credible fear of persecution under subsection (b)(1)(B). In no case may a stowaway be considered an applicant for admission or eligible for a hearing under section 1229a of this title."],[0,"(3) Inspection"],[1,"All aliens (including alien crewmen) who are applicants for admission or otherwise seeking admission or readmission to or transit through the United States shall be inspected by immigration officers."],[0,"(4) Withdrawal of application for admission"],[1,"An alien applying for admission may, in the discretion of the Attorney General and at any time, be permitted to withdraw the application for admission and depart immediately from the United States."],[0,"(5) Statements"],[1,"An applicant for admission may be required to state under oath any information sought by an immigration officer regarding the purposes and intentions of the applicant in seeking admission to the United States, including the applicant's intended length of stay and whether the applicant intends to remain permanently or become a United States citizen, and whether the applicant is inadmissible."],[0,"(b) Inspection of applicants for admission"],[0,"(1) Inspection of aliens arriving in the United States and certain other aliens who have not been admitted or paroled"],[0,"(A) Screening"],[0,"(i) In general"],[3,"If an immigration officer determines that an alien (other than an alien described in subparagraph (F)) who is arriving in the United States or is described in clause (iii) is inadmissible under section 1182(a)(6)(C) or 1182(a)(7) of this title, the officer shall order the alien removed from the United States without further hearing or review unless the alien indicates either an intention to apply for asylum under section 1158 of this title or a fear of persecution."],[0,"(ii) Claims for asylum"],[3,"If an immigration officer determines that an alien (other than an alien described in subparagraph (F)) who is arriving in the United States or is described in clause (iii) is inadmissible under section 1182(a)(6)(C) or 1182(a)(7) of this title and the alien indicates either an intention to apply for asylum under section 1158 of this title or a fear of persecution, the officer shall refer the alien for an interview by an asylum officer under subparagraph (B)."],[0,"(iii) Application to certain other aliens"],[0,"(I) In general"],[4,"The Attorney General may apply clauses (i) and (ii) of this subparagraph to any or all aliens described in subclause (II) as designated by the Attorney General. Such designation shall be in the sole and unreviewable discretion of the Attorney General and may be modified at any time."],[0,"(II) Aliens described"],[4,"An alien described in this clause is an alien who is not described in subparagraph (F), who has not been admitted or paroled into the United States, and who has not affirmatively shown, to the satisfaction of an immigration officer, that the alien has been physically present in the United States continuously for the 2-year period immediately prior to the date of the determination of inadmissibility under this subparagraph."],[0,"(B) Asylum interviews"],[0,"(i) Conduct by asylum officers"],[3,"An asylum officer shall conduct interviews of aliens referred under subparagraph (A)(ii), either at a port of entry or at such other place designated by the Attorney General."],[0,"(ii) Referral of certain aliens"],[3,"If the officer determines at the time of the interview that an alien has a credible fear of persecution (within the meaning of clause (v)), the alien shall be detained for further consideration of the application for asylum."],[0,"(iii) Removal without further review if no credible fear of persecution"],[0,"(I) In general"],[4,"Subject to subclause (III), if the officer determines that an alien does not have a credible fear of persecution, the officer shall order the alien removed from the United States without further hearing or review."],[0,"(II) Record of determination"],[4,"The officer shall prepare a written record of a determination under subclause (I). Such record shall include a summary of the material facts as stated by the applicant, such additional facts (if any) relied upon by the officer, and the officer's analysis of why, in the light of such facts, the alien has not established a credible fear of persecution. A copy of the officer's interview notes shall be attached to the written summary."],[0,"(III) Review of determination"],[4,"The Attorney General shall provide by regulation and upon the alien's request for prompt review by an immigration judge of a determination under subclause (I) that the alien does not have a credible fear of persecution. Such review shall include an opportunity for the alien to be heard and questioned by the immigration judge, either in person or by telephonic or video connection. Review shall be concluded as expeditiously as possible, to the maximum extent practicable within 24 hours, but in no case later than 7 days after the date of the determination under subclause (I)."],[0,"(IV) Mandatory detention"],[4,"Any alien subject to the procedures under this clause shall be detained pending a final determination of credible fear of persecution and, if found not to have such a fear, until removed."],[0,"(iv) Information about interviews"],[3,"The Attorney General shall provide information concerning the asylum interview described in this subparagraph to aliens who may be eligible. An alien who is eligible for such interview may consult with a person or persons of the alien's choosing prior to the interview or any review thereof, according to regulations prescribed by the Attorney General. Such consultation shall be at no expense to the Government and shall not unreasonably delay the process."],[0,"(v) \"Credible fear of persecution\" defined"],[3,"For purposes of this subparagraph, the term \"credible fear of persecution\" means that there is a significant possibility, taking into account the credibility of the statements made by the alien in support of the alien's claim and such other facts as are known to the officer, that the alien could establish eligibility for asylum under section 1158 of this title."],[0,"(C) Limitation on administrative review"],[2,"Except as provided in subparagraph (B)(iii)(III), a removal order entered in accordance with subparagraph (A)(i) or (B)(iii)(I) is not subject to administrative appeal, except that the Attorney General shall provide by regulation for prompt review of such an order under subparagraph (A)(i) against an alien who claims under oath, or as permitted under penalty of perjury under section 1746 of title 28, after having been warned of the penalties for falsely making such claim under such conditions, to have been lawfully admitted for permanent residence, to have been admitted as a refugee under section 1157 of this title, or to have been granted asylum under section 1158 of this title."],[0,"(D) Limit on collateral attacks"],[2,"In any action brought against an alien under section 1325(a) of this title or section 1326 of this title, the court shall not have jurisdiction to hear any claim attacking the validity of an order of removal entered under subparagraph (A)(i) or (B)(iii)."],[0,"(E) \"Asylum officer\" defined"],[2,"As used in this paragraph, the term \"asylum officer\" means an immigration officer who—"],[3,"(i) has had professional training in country conditions, asylum law, and interview techniques comparable to that provided to full-time adjudicators of applications under section 1158 of this title, and"],[3,"(ii) is supervised by an officer who meets the condition described in clause (i) and has had substantial experience adjudicating asylum applications."],[0,"(F) Exception"],[2,"Subparagraph (A) shall not apply to an alien who is a native or citizen of a country in the Western Hemisphere with whose government the United States does not have full diplomatic relations and who arrives by aircraft at a port of entry."],[0,"(G) Commonwealth of the Northern Mariana Islands"],[2,"Nothing in this subsection shall be construed to authorize or require any person described in section 1158(e) of this title to be permitted to apply for asylum under section 1158 of this title at any time before January 1, 2014."],[0,"(2) Inspection of other aliens"],[0,"(A) In general"],[2,"Subject to subparagraphs (B) and (C), in the case of an alien who is an applicant for admission, if the examining immigration officer determines that an alien seeking admission is not clearly and beyond a doubt entitled to be admitted, the alien shall be detained for a proceeding under section 1229a of this title."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1225?type=usc&year=mostrecent&link-type=html"},"head":"§1225. Inspection by immigration officers; expedited removal of inadmissible arriving aliens; referral for hearing","tname":"Aliens and Nationality","by":{"0":"35","1":"20, 50, 20, 20"}},{"t":"usc","label":"8 U.S.C. § 1226","url":"https://www.law.cornell.edu/uscode/text/8/1226","subs":["(a)","(a)(2)(A)","(a)(2)","(c)"],"stext":{"head":"§1226. Apprehension and detention of aliens","paras":[[0,"(a) Arrest, detention, and release"],[0,"On a warrant issued by the Attorney General, an alien may be arrested and detained pending a decision on whether the alien is to be removed from the United States. Except as provided in subsection (c) and pending such decision, the Attorney General—"],[1,"(1) may continue to detain the arrested alien; and"],[1,"(2) may release the alien on—"],[2,"(A) bond of at least $1,500 with security approved by, and containing conditions prescribed by, the Attorney General; or"],[2,"(B) conditional parole; but"],[1,"(3) may not provide the alien with work authorization (including an \"employment authorized\" endorsement or other appropriate work permit), unless the alien is lawfully admitted for permanent residence or otherwise would (without regard to removal proceedings) be provided such authorization."],[0,"(b) Revocation of bond or parole"],[0,"The Attorney General at any time may revoke a bond or parole authorized under subsection (a), rearrest the alien under the original warrant, and detain the alien."],[0,"(c) Detention of criminal aliens"],[0,"(1) Custody"],[1,"The Attorney General shall take into custody any alien who—"],[2,"(A) is inadmissible by reason of having committed any offense covered in section 1182(a)(2) of this title,"],[2,"(B) is deportable by reason of having committed any offense covered in section 1227(a)(2)(A)(ii), (A)(iii), (B), (C), or (D) of this title,"],[2,"(C) is deportable under section 1227(a)(2)(A)(i) of this title on the basis of an offense for which the alien has been sentence 1 to a term of imprisonment of at least 1 year, or"],[2,"(D) is inadmissible under section 1182(a)(3)(B) of this title or deportable under section 1227(a)(4)(B) of this title,"],[1,"when the alien is released, without regard to whether the alien is released on parole, supervised release, or probation, and without regard to whether the alien may be arrested or imprisoned again for the same offense."],[0,"(2) Release"],[1,"The Attorney General may release an alien described in paragraph (1) only if the Attorney General decides pursuant to section 3521 of title 18 that release of the alien from custody is necessary to provide protection to a witness, a potential witness, a person cooperating with an investigation into major criminal activity, or an immediate family member or close associate of a witness, potential witness, or person cooperating with such an investigation, and the alien satisfies the Attorney General that the alien will not pose a danger to the safety of other persons or of property and is likely to appear for any scheduled proceeding. A decision relating to such release shall take place in accordance with a procedure that considers the severity of the offense committed by the alien."],[0,"(d) Identification of criminal aliens"],[0,"(1) The Attorney General shall devise and implement a system—"],[1,"(A) to make available, daily (on a 24-hour basis), to Federal, State, and local authorities the investigative resources of the Service to determine whether individuals arrested by such authorities for aggravated felonies are aliens;"],[1,"(B) to designate and train officers and employees of the Service to serve as a liaison to Federal, State, and local law enforcement and correctional agencies and courts with respect to the arrest, conviction, and release of any alien charged with an aggravated felony; and"],[1,"(C) which uses computer resources to maintain a current record of aliens who have been convicted of an aggravated felony, and indicates those who have been removed."],[0,"(2) The record under paragraph (1)(C) shall be made available—"],[1,"(A) to inspectors at ports of entry and to border patrol agents at sector headquarters for purposes of immediate identification of any alien who was previously ordered removed and is seeking to reenter the United States, and"],[1,"(B) to officials of the Department of State for use in its automated visa lookout system."],[0,"(3) Upon the request of the governor or chief executive officer of any State, the Service shall provide assistance to State courts in the identification of aliens unlawfully present in the United States pending criminal prosecution."],[0,"(e) Judicial review"],[0,"The Attorney General's discretionary judgment regarding the application of this section shall not be subject to review. No court may set aside any action or decision by the Attorney General under this section regarding the detention or release of any alien or the grant, revocation, or denial of bond or parole."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1226?type=usc&year=mostrecent&link-type=html"},"head":"§1226. Apprehension and detention of aliens","tname":"Aliens and Nationality","by":{"0":"38, 8, 9, 38, 39, 45, 38","1":"passim, 50, 20","2":"14, 20"}},{"t":"usc","label":"8 U.S.C. § 1229a","url":"https://www.law.cornell.edu/uscode/text/8/1229a","subs":["(a)(1)"],"by":{"0":"35"}},{"t":"usc","label":"8 U.S.C. § 1231","url":"https://www.law.cornell.edu/uscode/text/8/1231","subs":["(a)","(a)(1)(A)","(a)(2)","(a)(3)","(a)(5)","(a)(6)","(h)","(a)(1)(B)","(b)(3)","(b)(3)(A)"],"stext":{"head":"§1231. Detention and removal of aliens ordered removed","paras":[[0,"(a) Detention, release, and removal of aliens ordered removed"],[0,"(1) Removal period"],[0,"(A) In general"],[2,"Except as otherwise provided in this section, when an alien is ordered removed, the Attorney General shall remove the alien from the United States within a period of 90 days (in this section referred to as the \"removal period\")."],[0,"(B) Beginning of period"],[2,"The removal period begins on the latest of the following:"],[3,"(i) The date the order of removal becomes administratively final."],[3,"(ii) If the removal order is judicially reviewed and if a court orders a stay of the removal of the alien, the date of the court's final order."],[3,"(iii) If the alien is detained or confined (except under an immigration process), the date the alien is released from detention or confinement."],[0,"(C) Suspension of period"],[2,"The removal period shall be extended beyond a period of 90 days and the alien may remain in detention during such extended period if the alien fails or refuses to make timely application in good faith for travel or other documents necessary to the alien's departure or conspires or acts to prevent the alien's removal subject to an order of removal."],[0,"(2) Detention"],[1,"During the removal period, the Attorney General shall detain the alien. Under no circumstance during the removal period shall the Attorney General release an alien who has been found inadmissible under section 1182(a)(2) or 1182(a)(3)(B) of this title or deportable under section 1227(a)(2) or 1227(a)(4)(B) of this title."],[0,"(3) Supervision after 90-day period"],[1,"If the alien does not leave or is not removed within the removal period, the alien, pending removal, shall be subject to supervision under regulations prescribed by the Attorney General. The regulations shall include provisions requiring the alien—"],[2,"(A) to appear before an immigration officer periodically for identification;"],[2,"(B) to submit, if necessary, to a medical and psychiatric examination at the expense of the United States Government;"],[2,"(C) to give information under oath about the alien's nationality, circumstances, habits, associations, and activities, and other information the Attorney General considers appropriate; and"],[2,"(D) to obey reasonable written restrictions on the alien's conduct or activities that the Attorney General prescribes for the alien."],[0,"(4) Aliens imprisoned, arrested, or on parole, supervised release, or probation"],[0,"(A) In general"],[2,"Except as provided in section 259(a) 1 of title 42 and paragraph (2),2 the Attorney General may not remove an alien who is sentenced to imprisonment until the alien is released from imprisonment. Parole, supervised release, probation, or possibility of arrest or further imprisonment is not a reason to defer removal."],[0,"(B) Exception for removal of nonviolent offenders prior to completion of sentence of imprisonment"],[2,"The Attorney General is authorized to remove an alien in accordance with applicable procedures under this chapter before the alien has completed a sentence of imprisonment—"],[3,"(i) in the case of an alien in the custody of the Attorney General, if the Attorney General determines that (I) the alien is confined pursuant to a final conviction for a nonviolent offense (other than an offense related to smuggling or harboring of aliens or an offense described in section 1101(a)(43)(B), (C), (E), (I), or (L) of this title 3 and (II) the removal of the alien is appropriate and in the best interest of the United States; or"],[3,"(ii) in the case of an alien in the custody of a State (or a political subdivision of a State), if the chief State official exercising authority with respect to the incarceration of the alien determines that (I) the alien is confined pursuant to a final conviction for a nonviolent offense (other than an offense described in section 1101(a)(43)(C) or (E) of this title), (II) the removal is appropriate and in the best interest of the State, and (III) submits a written request to the Attorney General that such alien be so removed."],[0,"(C) Notice"],[2,"Any alien removed pursuant to this paragraph shall be notified of the penalties under the laws of the United States relating to the reentry of deported aliens, particularly the expanded penalties for aliens removed under subparagraph (B)."],[0,"(D) No private right"],[2,"No cause or claim may be asserted under this paragraph against any official of the United States or of any State to compel the release, removal, or consideration for release or removal of any alien."],[0,"(5) Reinstatement of removal orders against aliens illegally reentering"],[1,"If the Attorney General finds that an alien has reentered the United States illegally after having been removed or having departed voluntarily, under an order of removal, the prior order of removal is reinstated from its original date and is not subject to being reopened or reviewed, the alien is not eligible and may not apply for any relief under this chapter, and the alien shall be removed under the prior order at any time after the reentry."],[0,"(6) Inadmissible or criminal aliens"],[1,"An alien ordered removed who is inadmissible under section 1182 of this title, removable under section 1227(a)(1)(C), 1227(a)(2), or 1227(a)(4) of this title or who has been determined by the Attorney General to be a risk to the community or unlikely to comply with the order of removal, may be detained beyond the removal period and, if released, shall be subject to the terms of supervision in paragraph (3)."],[0,"(7) Employment authorization"],[1,"No alien ordered removed shall be eligible to receive authorization to be employed in the United States unless the Attorney General makes a specific finding that—"],[2,"(A) the alien cannot be removed due to the refusal of all countries designated by the alien or under this section to receive the alien, or"],[2,"(B) the removal of the alien is otherwise impracticable or contrary to the public interest."],[0,"(b) Countries to which aliens may be removed"],[0,"(1) Aliens arriving at the United States"],[1,"Subject to paragraph (3)—"],[0,"(A) In general"],[2,"Except as provided by subparagraphs (B) and (C), an alien who arrives at the United States and with respect to whom proceedings under section 1229a of this title were initiated at the time of such alien's arrival shall be removed to the country in which the alien boarded the vessel or aircraft on which the alien arrived in the United States."],[0,"(B) Travel from contiguous territory"],[2,"If the alien boarded the vessel or aircraft on which the alien arrived in the United States in a foreign territory contiguous to the United States, an island adjacent to the United States, or an island adjacent to a foreign territory contiguous to the United States, and the alien is not a native, citizen, subject, or national of, or does not reside in, the territory or island, removal shall be to the country in which the alien boarded the vessel that transported the alien to the territory or island."],[0,"(C) Alternative countries"],[2,"If the government of the country designated in subparagraph (A) or (B) is unwilling to accept the alien into that country's territory, removal shall be to any of the following countries, as directed by the Attorney General:"],[3,"(i) The country of which the alien is a citizen, subject, or national."],[3,"(ii) The country in which the alien was born."],[3,"(iii) The country in which the alien has a residence."],[3,"(iv) A country with a government that will accept the alien into the country's territory if removal to each country described in a previous clause of this subparagraph is impracticable, inadvisable, or impossible."],[0,"(2) Other aliens"],[1,"Subject to paragraph (3)—"],[0,"(A) Selection of country by alien"],[2,"Except as otherwise provided in this paragraph—"],[3,"(i) any alien not described in paragraph (1) who has been ordered removed may designate one country to which the alien wants to be removed, and"],[3,"(ii) the Attorney General shall remove the alien to the country the alien so designates."],[0,"(B) Limitation on designation"],[2,"An alien may designate under subparagraph (A)(i) a foreign territory contiguous to the United States, an adjacent island, or an island adjacent to a foreign territory contiguous to the United States as the place to which the alien is to be removed only if the alien is a native, citizen, subject, or national of, or has resided in, that designated territory or island."],[0,"(C) Disregarding designation"],[2,"The Attorney General may disregard a designation under subparagraph (A)(i) if—"],[3,"(i) the alien fails to designate a country promptly;"],[3,"(ii) the government of the country does not inform the Attorney General finally, within 30 days after the date the Attorney General first inquires, whether the government will accept the alien into the country;"],[3,"(iii) the government of the country is not willing to accept the alien into the country; or"],[3,"(iv) the Attorney General decides that removing the alien to the country is prejudicial to the United States."],[0,"(D) Alternative country"],[2,"If an alien is not removed to a country designated under subparagraph (A)(i), the Attorney General shall remove the alien to a country of which the alien is a subject, national, or citizen unless the government of the country—"],[3,"(i) does not inform the Attorney General or the alien finally, within 30 days after the date the Attorney General first inquires or within another period of time the Attorney General decides is reasonable, whether the government will accept the alien into the country; or"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1231?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§1231. Detention and removal of aliens ordered removed","tname":"Aliens and Nationality","by":{"0":"35, 35, 35, 35, 35, 35, 35, 35","1":"passim, 19, 7, 7, 7, 19, 36, 19, 22, 24, 4, 10, passim, 5, 5, 37","2":"1, passim, 18"}},{"t":"usc","label":"8 U.S.C. § 1232","url":"https://www.law.cornell.edu/uscode/text/8/1232","subs":["(a)(5)(D)(i)"],"by":{"0":"35"}},{"t":"usc","label":"8 U.S.C. § 1252","url":"https://www.law.cornell.edu/uscode/text/8/1252","subs":["(a)(2)","(a)(2)(D)","(a)(5)","(b)(9)","(e)(1)(B)","(e)(3)(A)","(e)(3)(A)(i)","(e)(4)(B)","(a)(1)","(a)(2)(A)(i)","(f)","(f)(1)","(a)(2)(A)"],"stext":{"head":"§1252. Judicial review of orders of removal","paras":[[0,"(a) Applicable provisions"],[0,"(1) General orders of removal"],[1,"Judicial review of a final order of removal (other than an order of removal without a hearing pursuant to section 1225(b)(1) of this title) is governed only by chapter 158 of title 28, except as provided in subsection (b) and except that the court may not order the taking of additional evidence under section 2347(c) of such title."],[0,"(2) Matters not subject to judicial review"],[0,"(A) Review relating to section 1225(b)(1)"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, no court shall have jurisdiction to review—"],[3,"(i) except as provided in subsection (e), any individual determination or to entertain any other cause or claim arising from or relating to the implementation or operation of an order of removal pursuant to section 1225(b)(1) of this title,"],[3,"(ii) except as provided in subsection (e), a decision by the Attorney General to invoke the provisions of such section,"],[3,"(iii) the application of such section to individual aliens, including the determination made under section 1225(b)(1)(B) of this title, or"],[3,"(iv) except as provided in subsection (e), procedures and policies adopted by the Attorney General to implement the provisions of section 1225(b)(1) of this title."],[0,"(B) Denials of discretionary relief"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, and except as provided in subparagraph (D), and regardless of whether the judgment, decision, or action is made in removal proceedings, no court shall have jurisdiction to review—"],[3,"(i) any judgment regarding the granting of relief under section 1182(h), 1182(i), 1229b, 1229c, or 1255 of this title, or"],[3,"(ii) any other decision or action of the Attorney General or the Secretary of Homeland Security the authority for which is specified under this subchapter to be in the discretion of the Attorney General or the Secretary of Homeland Security, other than the granting of relief under section 1158(a) of this title."],[0,"(C) Orders against criminal aliens"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, and except as provided in subparagraph (D), no court shall have jurisdiction to review any final order of removal against an alien who is removable by reason of having committed a criminal offense covered in section 1182(a)(2) or 1227(a)(2)(A)(iii), (B), (C), or (D) of this title, or any offense covered by section 1227(a)(2)(A)(ii) of this title for which both predicate offenses are, without regard to their date of commission, otherwise covered by section 1227(a)(2)(A)(i) of this title."],[0,"(D) Judicial review of certain legal claims"],[2,"Nothing in subparagraph (B) or (C), or in any other provision of this chapter (other than this section) which limits or eliminates judicial review, shall be construed as precluding review of constitutional claims or questions of law raised upon a petition for review filed with an appropriate court of appeals in accordance with this section."],[0,"(3) Treatment of certain decisions"],[1,"No alien shall have a right to appeal from a decision of an immigration judge which is based solely on a certification described in section 1229a(c)(1)(B) of this title."],[0,"(4) Claims under the United Nations Convention"],[1,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, a petition for review filed with an appropriate court of appeals in accordance with this section shall be the sole and exclusive means for judicial review of any cause or claim under the United Nations Convention Against Torture and Other Forms of Cruel, Inhuman, or Degrading Treatment or Punishment, except as provided in subsection (e)."],[0,"(5) Exclusive means of review"],[1,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, a petition for review filed with an appropriate court of appeals in accordance with this section shall be the sole and exclusive means for judicial review of an order of removal entered or issued under any provision of this chapter, except as provided in subsection (e). For purposes of this chapter, in every provision that limits or eliminates judicial review or jurisdiction to review, the terms \"judicial review\" and \"jurisdiction to review\" include habeas corpus review pursuant to section 2241 of title 28, or any other habeas corpus provision, sections 1361 and 1651 of such title, and review pursuant to any other provision of law (statutory or nonstatutory)."],[0,"(b) Requirements for review of orders of removal"],[0,"With respect to review of an order of removal under subsection (a)(1), the following requirements apply:"],[0,"(1) Deadline"],[1,"The petition for review must be filed not later than 30 days after the date of the final order of removal."],[0,"(2) Venue and forms"],[1,"The petition for review shall be filed with the court of appeals for the judicial circuit in which the immigration judge completed the proceedings. The record and briefs do not have to be printed. The court of appeals shall review the proceeding on a typewritten record and on typewritten briefs."],[0,"(3) Service"],[0,"(A) In general"],[2,"The respondent is the Attorney General. The petition shall be served on the Attorney General and on the officer or employee of the Service in charge of the Service district in which the final order of removal under section 1229a of this title was entered."],[0,"(B) Stay of order"],[2,"Service of the petition on the officer or employee does not stay the removal of an alien pending the court's decision on the petition, unless the court orders otherwise."],[0,"(C) Alien's brief"],[2,"The alien shall serve and file a brief in connection with a petition for judicial review not later than 40 days after the date on which the administrative record is available, and may serve and file a reply brief not later than 14 days after service of the brief of the Attorney General, and the court may not extend these deadlines except upon motion for good cause shown. If an alien fails to file a brief within the time provided in this paragraph, the court shall dismiss the appeal unless a manifest injustice would result."],[0,"(4) Scope and standard for review"],[1,"Except as provided in paragraph (5)(B)—"],[2,"(A) the court of appeals shall decide the petition only on the administrative record on which the order of removal is based,"],[2,"(B) the administrative findings of fact are conclusive unless any reasonable adjudicator would be compelled to conclude to the contrary,"],[2,"(C) a decision that an alien is not eligible for admission to the United States is conclusive unless manifestly contrary to law, and"],[2,"(D) the Attorney General's discretionary judgment whether to grant relief under section 1158(a) of this title shall be conclusive unless manifestly contrary to the law and an abuse of discretion."],[1,"No court shall reverse a determination made by a trier of fact with respect to the availability of corroborating evidence, as described in section 1158(b)(1)(B), 1229a(c)(4)(B), or 1231(b)(3)(C) of this title, unless the court finds, pursuant to subsection (b)(4)(B), that a reasonable trier of fact is compelled to conclude that such corroborating evidence is unavailable."],[0,"(5) Treatment of nationality claims"],[0,"(A) Court determination if no issue of fact"],[2,"If the petitioner claims to be a national of the United States and the court of appeals finds from the pleadings and affidavits that no genuine issue of material fact about the petitioner's nationality is presented, the court shall decide the nationality claim."],[0,"(B) Transfer if issue of fact"],[2,"If the petitioner claims to be a national of the United States and the court of appeals finds that a genuine issue of material fact about the petitioner's nationality is presented, the court shall transfer the proceeding to the district court of the United States for the judicial district in which the petitioner resides for a new hearing on the nationality claim and a decision on that claim as if an action had been brought in the district court under section 2201 of title 28."],[0,"(C) Limitation on determination"],[2,"The petitioner may have such nationality claim decided only as provided in this paragraph."],[0,"(6) Consolidation with review of motions to reopen or reconsider"],[1,"When a petitioner seeks review of an order under this section, any review sought of a motion to reopen or reconsider the order shall be consolidated with the review of the order."],[0,"(7) Challenge to validity of orders in certain criminal proceedings"],[0,"(A) In general"],[2,"If the validity of an order of removal has not been judicially decided, a defendant in a criminal proceeding charged with violating section 1253(a) of this title may challenge the validity of the order in the criminal proceeding only by filing a separate motion before trial. The district court, without a jury, shall decide the motion before trial."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1252?type=usc&year=mostrecent&link-type=html"},"op":10,"head":"§1252. Judicial review of orders of removal","tname":"Aliens and Nationality","by":{"0":"36, 36, 36, 36, 36, 36, 36, 36, 36, 36, 36, 36","1":"51, 57, 6, 51, 18, 57, 3, 4, passim","2":"4, 3, 10, passim"}},{"t":"usc","label":"8 U.S.C. § 1551","url":"https://www.law.cornell.edu/uscode/text/8/1551","by":{"0":"36"}},{"t":"usc","label":"28 U.S.C. § 1341","url":"https://www.law.cornell.edu/uscode/text/28/1341","stext":{"head":"§1341. Taxes by States","paras":[[0,"The district courts shall not enjoin, suspend or restrain the assessment, levy or collection of any tax under State law where a plain, speedy and efficient remedy may be had in the courts of such State."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1341?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1341. Taxes by States","tname":"Judiciary and Judicial Procedure","by":{"0":"17, 18, 18"}},{"t":"usc","label":"6 U.S.C. § 202","url":"https://www.law.cornell.edu/uscode/text/6/202","subs":["(3)"],"by":{"0":"36"}},{"t":"usc","label":"6 U.S.C. § 251","url":"https://www.law.cornell.edu/uscode/text/6/251","by":{"0":"36"}},{"t":"usc","label":"6 U.S.C. § 271","url":"https://www.law.cornell.edu/uscode/text/6/271","subs":["(b)"],"by":{"0":"36"}},{"t":"usc","label":"6 U.S.C. § 542","url":"https://www.law.cornell.edu/uscode/text/6/542","by":{"0":"36"}},{"t":"usc","label":"6 U.S.C. § 557","url":"https://www.law.cornell.edu/uscode/text/6/557","by":{"0":"36"}},{"t":"usc","label":"28 U.S.C. § 1253","url":"https://www.law.cornell.edu/uscode/text/28/1253","by":{"0":"18"}},{"t":"usc","label":"28 U.S.C. § 2281","url":"https://www.law.cornell.edu/uscode/text/28/2281","subs":["(1970)"],"by":{"0":"20"}},{"t":"usc","label":"42 U.S.C. § 405","url":"https://www.law.cornell.edu/uscode/text/42/405","subs":["(g)(1976)"],"stext":{"head":"§405. Evidence, procedure, and certification for payments","paras":[[0,"(a) Rules and regulations; procedures"],[0,"The Commissioner of Social Security shall have full power and authority to make rules and regulations and to establish procedures, not inconsistent with the provisions of this subchapter, which are necessary or appropriate to carry out such provisions, and shall adopt reasonable and proper rules and regulations to regulate and provide for the nature and extent of the proofs and evidence and the method of taking and furnishing the same in order to establish the right to benefits hereunder."],[0,"(b) Administrative determination of entitlement to benefits; findings of fact; hearings; investigations; evidentiary hearings in reconsiderations of disability benefit terminations; subsequent applications"],[0,"(1) The Commissioner of Social Security is directed to make findings of fact, and decisions as to the rights of any individual applying for a payment under this subchapter. Any such decision by the Commissioner of Social Security which involves a determination of disability and which is in whole or in part unfavorable to such individual shall contain a statement of the case, in understandable language, setting forth a discussion of the evidence, and stating the Commissioner's determination and the reason or reasons upon which it is based. Upon request by any such individual or upon request by a wife, divorced wife, widow, surviving divorced wife, surviving divorced mother, surviving divorced father, husband, divorced husband, widower, surviving divorced husband, child, or parent who makes a showing in writing that his or her rights may be prejudiced by any decision the Commissioner of Social Security has rendered, the Commissioner shall give such applicant and such other individual reasonable notice and opportunity for a hearing with respect to such decision, and, if a hearing is held, shall, on the basis of evidence adduced at the hearing, affirm, modify, or reverse the Commissioner's findings of fact and such decision. Any such request with respect to such a decision must be filed within sixty days after notice of such decision is received by the individual making such request. The Commissioner of Social Security is further authorized, on the Commissioner's own motion, to hold such hearings and to conduct such investigations and other proceedings as the Commissioner may deem necessary or proper for the administration of this subchapter. In the course of any hearing, investigation, or other proceeding, the Commissioner may administer oaths and affirmations, examine witnesses, and receive evidence. Evidence may be received at any hearing before the Commissioner of Social Security even though inadmissible under rules of evidence applicable to court procedure."],[0,"(2) In any case where—"],[1,"(A) an individual is a recipient of disability insurance benefits, or of child's, widow's, or widower's insurance benefits based on disability,"],[1,"(B) the physical or mental impairment on the basis of which such benefits are payable is found to have ceased, not to have existed, or to no longer be disabling, and"],[1,"(C) as a consequence of the finding described in subparagraph (B), such individual is determined by the Commissioner of Social Security not to be entitled to such benefits,"],[0,"any reconsideration of the finding described in subparagraph (B), in connection with a reconsideration by the Commissioner of Social Security (before any hearing under paragraph (1) on the issue of such entitlement) of the Commissioner's determination described in subparagraph (C), shall be made only after opportunity for an evidentiary hearing, with regard to the finding described in subparagraph (B), which is reasonably accessible to such individual. Any reconsideration of a finding described in subparagraph (B) may be made either by the State agency or the Commissioner of Social Security where the finding was originally made by the State agency, and shall be made by the Commissioner of Social Security where the finding was originally made by the Commissioner of Social Security. In the case of a reconsideration by a State agency of a finding described in subparagraph (B) which was originally made by such State agency, the evidentiary hearing shall be held by an adjudicatory unit of the State agency other than the unit that made the finding described in subparagraph (B). In the case of a reconsideration by the Commissioner of Social Security of a finding described in subparagraph (B) which was originally made by the Commissioner of Social Security, the evidentiary hearing shall be held by a person other than the person or persons who made the finding described in subparagraph (B)."],[0,"(3)(A) A failure to timely request review of an initial adverse determination with respect to an application for any benefit under this subchapter or an adverse determination on reconsideration of such an initial determination shall not serve as a basis for denial of a subsequent application for any benefit under this subchapter if the applicant demonstrates that the applicant, or any other individual referred to in paragraph (1), failed to so request such a review acting in good faith reliance upon incorrect, incomplete, or misleading information, relating to the consequences of reapplying for benefits in lieu of seeking review of an adverse determination, provided by any officer or employee of the Social Security Administration or any State agency acting under section 421 of this title."],[0,"(B) In any notice of an adverse determination with respect to which a review may be requested under paragraph (1), the Commissioner of Social Security shall describe in clear and specific language the effect on possible entitlement to benefits under this subchapter of choosing to reapply in lieu of requesting review of the determination."],[0,"(c) Wage records"],[0,"(1) For the purposes of this subsection—"],[1,"(A) The term \"year\" means a calendar year when used with respect to wages and a taxable year when used with respect to self-employment income."],[1,"(B) The term \"time limitation\" means a period of three years, three months, and fifteen days."],[1,"(C) The term \"survivor\" means an individual's spouse, surviving divorced wife, surviving divorced husband, surviving divorced mother, surviving divorced father, child, or parent, who survives such individual."],[1,"(D) The term \"period\" when used with respect to self-employment income means a taxable year and when used with respect to wages means—"],[2,"(i) a quarter if wages were reported or should have been reported on a quarterly basis on tax returns filed with the Secretary of the Treasury or his delegate under section 6011 of the Internal Revenue Code of 1986 or regulations thereunder (or on reports filed by a State under section 418(e) 1 of this title (as in effect prior to December 31, 1986) or regulations thereunder),"],[2,"(ii) a year if wages were reported or should have been reported on a yearly basis on such tax returns or reports, or"],[2,"(iii) the half year beginning January 1 or July 1 in the case of wages which were reported or should have been reported for calendar year 1937."],[0,"(2)(A) On the basis of information obtained by or submitted to the Commissioner of Social Security, and after such verification thereof as the Commissioner deems necessary, the Commissioner of Social Security shall establish and maintain records of the amounts of wages paid to, and the amounts of self-employment income derived by, each individual and of the periods in which such wages were paid and such income was derived and, upon request, shall inform any individual or his survivor, or the legal representative of such individual or his estate, of the amounts of wages and self-employment income of such individual and the periods during which such wages were paid and such income was derived, as shown by such records at the time of such request."],[0,"(B)(i) In carrying out the Commissioner's duties under subparagraph (A) and subparagraph (F), the Commissioner of Social Security shall take affirmative measures to assure that social security account numbers will, to the maximum extent practicable, be assigned to all members of appropriate groups or categories of individuals by assigning such numbers (or ascertaining that such numbers have already been assigned):"],[1,"(I) to aliens at the time of their lawful admission to the United States either for permanent residence or under other authority of law permitting them to engage in employment in the United States and to other aliens at such time as their status is so changed as to make it lawful for them to engage in such employment;"],[1,"(II) to any individual who is an applicant for or recipient of benefits under any program financed in whole or in part from Federal funds including any child on whose behalf such benefits are claimed by another person; and"],[1,"(III) to any other individual when it appears that he could have been but was not assigned an account number under the provisions of subclauses (I) or (II) but only after such investigation as is necessary to establish to the satisfaction of the Commissioner of Social Security, the identity of such individual, the fact that an account number has not already been assigned to such individual, and the fact that such individual is a citizen or a noncitizen who is not, because of his alien status, prohibited from engaging in employment;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/405?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§405. Evidence, procedure, and certification for payments","tname":"The Public Health and Welfare","by":{"0":"30, 31"}},{"t":"rule","label":"Fed. R. Civ. P. 23","url":"https://www.law.cornell.edu/rules/frcp/rule_23","subs":["(b)(2)"],"by":{"0":"32","1":"57, 58, 48"}},{"t":"case","label":"Abramski v. United States","cite":"573 U.S. 169","y":2014,"id":"2013/12-1493","sc":1,"sum":"The Court held that a firearm purchaser's intent to sell their gun to another buyer is necessary information for the seller's records.","sumSrc":"Oyez","by":{"1":"25"}},{"t":"case","label":"Adarand Constructors, Inc. v. Mineta","cite":"534 U.S. 103","y":2001,"id":"2001/00-730","sc":1,"sum":"After Adarand asserted that it was only challenging the rules pertaining to the direct procurement of DOT funds for highway construction on federal lands rather than any part of the DOT's DBE program as it pertained to state and local procurement, the Court concluded that the posture of the case had changed.","sumSrc":"Oyez","by":{"1":"49"}},{"t":"case","label":"Addington v. Texas","cite":"441 U.S. 418","y":1979,"id":"1978/77-5992","sc":1,"ar":2,"sum":"The Court held that the standard of proof required in a civil case involving involuntary commitment to a mental health facility must be higher than a preponderance of the evidence, but that the “beyond a reasonable doubt” standard was not constitutionally required.","sumSrc":"Oyez","by":{"1":"31, 38"}},{"t":"case","label":"Am. Immigr. Laws. Ass’n v. Reno","cite":"199 F.3d 1352","y":2000,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/199/1352/","by":{"1":"55"}},{"t":"case","label":"Arbaugh v. Y & H Corp.","cite":"546 U.S. 500","y":2006,"id":"2005/04-944","sc":1,"sum":"The Court held that the number-of-employees requirement is an element of the merits of a Title VII claim, not a jurisdictional limitation.","sumSrc":"Oyez","by":{"1":"47","2":"2"}},{"t":"case","label":"Avco Corp. v. Aero Lodge No. 735, Int’l Ass’n of Machinists & Aerospace Workers","cite":"390 U.S. 557","y":1968,"id":"1967/445","sc":1,"ar":1,"sum":"Petitioner, employer, brought suit in a Tennessee court to enjoin respondent union and its members from striking in violation of a \"no-strike\" clause in the collective bargaining agreement. The state court issued an ex parte injunction. Respondents moved in Federal District Court for removal of the case, and dissolution of the injunction. The District Court ruled that the action was within its original jurisdiction, …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"47"}},{"t":"case","label":"Bankamerica Corp. v. United States","cite":"462 U.S. 122","y":1983,"id":"1982/81-1487","sc":1,"sum":"The fourth paragraph of § 8 does not bar interlocking directorates between a bank and a competing insurance company.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"26"}},{"t":"case","label":"Barnhart v. Sigmon Coal Co., Inc.","cite":"534 U.S. 438","y":2002,"id":"2001/00-1307","sc":1,"sum":"The Court held that the Act did not permit the Commissioner to assign retired miners to the successors in interest of out-of-business signatory operators, since the companies were not related to such operators under the Act's statutory definitions.","sumSrc":"Oyez","by":{"1":"51"}},{"t":"case","label":"Brownback v. King","cite":"141 S. Ct. 740","y":2021,"id":"2020/19-546","sc":1,"op":1,"sum":"The District Court’s order dismissing King’s Federal Tort Claims Act claims was a judgment on the merits that can trigger the Act’s judgment bar to block his Bivens claims. See 28 U. S. C. §2676; Bivens v. Six Unknown Fed. Narcotics Agents, 403 U. S. 388.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"26"}},{"t":"case","label":"Casas-Castrillon v. Dep’t of Homeland Sec.","cite":"535 F.3d 942","y":2008,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/535/942/","by":{"1":"45"}},{"t":"case","label":"Chrysafis v. Marks","cite":"141 S. Ct. 2482","y":2021,"url":"https://www.courtlistener.com/c/S.%20Ct./141/2482/","sc":1,"sum":"Observing that the Court “has ‘read an implicit limitation’ into 1231(a)(6) ‘in light of the Constitution’s demands’” (quoting Zadvydas, 533 U.S. at 689).","sumSrc":"brief:1","by":{"1":"42"}},{"t":"case","label":"Clark v. Martinez","cite":"543 U.S. 371","y":2005,"id":"2004/03-878","sc":1,"sum":"The Court said the requirement that immigrants be detained no longer than reasonably necessary for deportation applied to both admissible and inadmissible immigrants. Because readmission to Cuba was unforeseeable, the detentions of Martinez and Benitez were unreasonable.","sumSrc":"Oyez","by":{"1":"20, 56","2":"16"}},{"t":"case","label":"Cnty. of Riverside v. McLaughlin","cite":"500 U.S. 44","y":1991,"id":"1990/89-1817","sc":1,"sum":"The Court held that Riverside's actions did not comply with the Gerstein precedent. Justice O'Connor argued that it was the state's burden to demonstrate extraordinary circumstances when delaying probable cause determinations beyond 48 hours. The lower court in this case had placed that responsibility on the accused. Intervening weekends or complicated pretrial proceedings were not legitimate reasons for delay.","sumSrc":"Oyez","by":{"1":"32"}},{"t":"case","label":"Coolidge v. New Hampshire","cite":"403 U.S. 443","y":1971,"id":"1970/323","sc":1,"sum":"The Court held that the searches and seizures of Coolidge's property were unconstitutional.","sumSrc":"Oyez","by":{"1":"40","2":"22"}},{"t":"case","label":"Crowell v. Benson","cite":"285 U.S. 22","y":1932,"id":"scdb/1931-083","sc":1,"sum":"(1) As the claims are governed by the maritime law and within the admiralty jurisdiction, trial by jury is not required by the Seventh Amendment. P.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"3"}},{"t":"case","label":"Foucha v. Louisiana","cite":"504 U.S. 71","y":1992,"id":"1991/90-5844","sc":1,"sum":"The judgment is reversed. 563 So. 2d 1138, reversed. JUSTICE WHITE delivered the opinion of the Court with respect to Parts I and II, concluding that the Louisiana statute violates the Due Process Clause because it allows an insanity acquittee to be committed to a mental institution until he is able to demonstrate that he is not dangerous to himself and others, even though he does not suffer from any mental illness. …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"2, 33, 38, 42"}},{"t":"case","label":"Gerstein v. Pugh","cite":"420 U.S. 103","y":1975,"id":"1973/73-477","sc":1,"sum":"The Court held that the Fourth Amendment entitles a person arrested without a warrant and charged by information to a timely preliminary hearing on probable cause.","sumSrc":"Oyez","by":{"1":"32, 40"}},{"t":"case","label":"Grace v. Barr","cite":"965 F.3d 883","y":2020,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/965/883/","op":1,"ar":1,"sum":"Explaining that 1252(f)(1) “refers only to ‘the operation of the provisions’—i.e., the statutory provisions themselves, and thus places no restriction on the district court’s authority to enjoin agency action found to be unlawful”.","sumSrc":"brief:1","by":{"1":"50"}},{"t":"case","label":"Haitian Refugee Ctr. v. Smith","cite":"676 F.2d 1023","y":1982,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/676/1023/","by":{"1":"56"}},{"t":"case","label":"Hamdi v. Rumsfeld","cite":"542 U.S. 507","y":2004,"id":"2003/03-6696","sc":1,"sum":"The Court held that individuals held in military confinement by the national government have a right, under the Fifth Amendment, to appeal that confinement in front of a neutral decision-making body.","sumSrc":"Oyez","by":{"1":"40"}},{"t":"case","label":"Hutto v. Finney","cite":"437 U.S. 678","y":1978,"id":"1977/76-1660","sc":1,"sum":"The Court held that punitive isolation for longer than thirty days in Arkansas prisons constituted cruel and unusual punishment and violated the Constitution. Justice Stevens conceded that isolation in and of itself was not necessarily unconstitutional and may in fact serve an important, legitimate interest in administering a prison.","sumSrc":"Oyez","by":{"1":"32"}},{"t":"case","label":"INS v. St. Cyr","cite":"533 U.S. 289","y":2001,"id":"2000/00-767","sc":1,"sum":"The Court held that habeas jurisdiction was not repealed by AEDPA and IIRIRA.","sumSrc":"Oyez","by":{"1":"30"}},{"t":"case","label":"Jackson v. Indiana","cite":"406 U.S. 715","y":1972,"id":"1971/70-5009","sc":1,"sum":"The Indiana procedure for pretrial commitment of incompetent criminal defendants set forth in Ind. Ann. Stat. § 9-1706a provides that a trial judge with \"reasonable ground\" to believe the defendant to be incompetent to stand trial must appoint two examining physicians and schedule a competency hearing, at which the defendant may introduce evidence. If the court, on the basis of thephysicians' report and \"other …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"31, 38, 42"}},{"t":"case","label":"Kansas v. Hendricks","cite":"521 U.S. 346","y":1997,"id":"1996/95-1649","sc":1,"op":1,"sum":"Despite Hendricks' claim that a certification of \"mental illness\" alone was too arbitrary to sustain a civil commitment order, the Court held that the Act met substantive due process standards by requiring considerable evidence of past violent sexual behavior and a present mental inclination to repeat such offenses.","sumSrc":"Oyez","by":{"1":"39, 40, 42"}},{"t":"case","label":"Kossov v. INS","cite":"132 F.3d 405","y":1998,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/132/405/","by":{"1":"6"}},{"t":"case","label":"Lopez v. Davis","cite":"531 U.S. 230","y":2001,"id":"2000/99-7504","sc":1,"sum":"The Court held that the categorically denial of early release to a prisoner who committed felony using firearm is a permissible exercise of the BOP's discretion, even if the prisoner has successfully completed a substance abuse program. \"The Bureau reasonably concluded that an inmate's prior involvement with firearms, in connection with the commission of a felony, suggests his readiness to resort to life-endangering violence and therefore appropriately determines the early release decision,\" wrote Justice Ginsburg for the majority.","sumSrc":"Oyez","by":{"1":"19"}},{"t":"case","label":"Madison v. Alabama","cite":"139 S. Ct. 718","y":2019,"id":"2018/17-7505","sc":1,"sum":"The Eighth Amendment may permit executing a prisoner even if he cannot remember committing his crime but it may prohibit executing a prisoner who suffers from dementia or another disorder rather than psychotic delusions.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"49"}},{"t":"case","label":"Mathews v. Diaz","cite":"426 U.S. 67","y":1976,"id":"1974/73-1046","sc":1,"sum":"Title 42 U. S. C. § 1395o (2) qualifies for enrollment in the Medicare supplemental medical insurance program residents of the United States who are 65 or older, but in subsection (B) denies eligibility to aliens unless they have been admitted for permanent residence and also have resided in the United States for at least five years. Appellee Diaz filed a class action suit in the District Court attacking the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"35"}},{"t":"case","label":"McNary v. Haitian Refugee Ctr., Inc.","cite":"498 U.S. 479","y":1991,"id":"1990/89-1332","sc":1,"sum":"The District Court had federal-question jurisdiction to hear respondents' constitutional and statutory challenges to the INS procedures.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"56"}},{"t":"case","label":"McNeil v. Dir., Patuxent Inst.","cite":"407 U.S. 245","y":1972,"id":"1971/71-5144","sc":1,"sum":"In the circumstances of this case, it is a denial of due process to continue to hold petitioner on the basis of an ex parte order committing him to observation without the procedural safeguards commensurate with a long-term commitment, Jackson v. Indiana, 406 U. S. 715; and without affording him those safeguards his further detention cannot be justified as analogous to confinement for civil contempt. pr for any …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"31, 33"}},{"t":"case","label":"Moncrieffe v. Holder","cite":"569 U.S. 184","y":2013,"id":"2012/11-702","sc":1,"op":1,"sum":"The Court found that distribution of small amounts of marijuana does not constitute an aggravated felony and thus, does not require deportation of the distributor.","sumSrc":"Oyez","by":{"1":"5"}},{"t":"case","label":"Muniz v. Hoffman","cite":"422 U.S. 454","y":1975,"id":"1974/73-1924","sc":1,"sum":"After their request for a jury trial was denied, petitioners, a labor union officer and the union, were adjudged guilty of criminal contempt for violating temporary injunctions issued by the District Court pursuant to § 10 (1) of the National Labor Relations Act (NLRA) against picketing of an employer pending the National Labor Relations Board's final disposition of the employer's unfair labor practice charge …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"33"}},{"t":"case","label":"Murray’s Lessee v. Hoboken Land & Improvement Co.","cite":"59 U.S. 272","y":1856,"id":"1850-1900/59us272","sc":1,"sum":"The Court found that \"due process of law\" meant that all citizens be tried \"by the law of the land,\" a concept established by the Magna Carta.","sumSrc":"Oyez","by":{"1":"29"}},{"t":"case","label":"Owen v. City of Independence","cite":"445 U.S. 622","y":1980,"id":"1979/78-1779","sc":1,"sum":"A municipality has no immunity from liability under § 1983 flowing from its constitutional violations and may not assert the good faith of its officers as a defense to such liability.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"53"}},{"t":"case","label":"Porter v. Warner Holding Co.","cite":"328 U.S. 395","y":1946,"id":"scdb/1945-032","sc":1,"op":1,"sum":"1. In an.enforcement proceeding under § 205 (a) of the Emergency Price Control Act of 1942, a Federal District Court has power to order restitution of rents collected by a landlord in excess of maximums established by regulations issued under the Act.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"50"}},{"t":"case","label":"Reno v. Catholic Soc. Servs., Inc.","cite":"509 U.S. 43","y":1993,"id":"1992/91-1826","sc":1,"sum":"The record is insufficient to allow this Court to decide all issues necessary to determine whether the District Courts had jurisdiction.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"56"}},{"t":"case","label":"Schall v. Martin","cite":"467 U.S. 253","y":1984,"id":"1983/82-1248","sc":1,"sum":"Held that pretrial detention of juveniles does not violate the right of Due Process. The pretrial detention serves the legitimate purpose of protecting both the state and the juvenile from further crimes.","sumSrc":"Oyez","by":{"1":"39, 40"}},{"t":"case","label":"Sessions v. Dimaya","cite":"138 S. Ct. 1204","y":2018,"id":"2017/15-1498","sc":1,"op":3,"sum":"A case in which the Court struck down the Immigration and Nationality Act’s “crime of violence” provision as unconstitutionally vague in violation of the Due Process Clause of the Fifth Amendment.","sumSrc":"Oyez","by":{"1":"35"}},{"t":"case","label":"Shadwick v. City of Tampa","cite":"407 U.S. 345","y":1972,"id":"1971/71-5445","sc":1,"sum":"City charter provision authorizing -municipal court clerks to issue arrest warrants for breach of municipal ordinances held to comport with requirements of the Fourth Amendment that warrants be issued by a neutral and detached magistrate who must be capable of determining whether probable cause exists for issuance of the warrant. The clerks, though laymen, worked within the judicial branch under supervision of …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"2, 40","2":"22"}},{"t":"case","label":"Smith v. City of Jackson","cite":"544 U.S. 228","y":2005,"id":"2004/03-1160","sc":1,"sum":"The Court held that ADEA authorized recovery in disparate-impact cases, but that in this case petitioners failed to set forth a valid claim. The Court relied on its 1971 decision in Griggs v. Duke Power, where the Court first authorized disparate-impact claims brought under Title VII of the Civil Rights Act of 1964.","sumSrc":"Oyez","by":{"1":"24"}},{"t":"case","label":"Steel Co. v. Citizens for Better Env’t","cite":"523 U.S. 83","y":1998,"id":"1997/96-643","sc":1,"sum":"The Court held, because none of the relief sought would likely remedy its alleged injury in fact, that Citizens For A Better Environment lacked standing to maintain suit and that the Court and lower federal courts lack the jurisdiction to entertain it. While all nine Justices agreed that the organization lacked standing, they disagreed on the reasons.","sumSrc":"Oyez","by":{"1":"47"}},{"t":"case","label":"Texas v. Biden, -- F. Supp. 3d --","cite":"2021 WL 3603341","y":2021,"court":"N.D. Tex. Aug. 13","by":{"1":"50"}},{"t":"case","label":"United States v. Davis","cite":"139 S. Ct. 2319","y":2019,"id":"2018/18-431","sc":1,"sum":"Title 18 U. S. C. §924(c)(3)(B), which provides enhanced penalties for using a firearm during a “crime of violence,” is unconstitutionally vague.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"24"}},{"t":"case","label":"United States v. Hare","cite":"873 F.2d 796","y":1989,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/873/796/","by":{"1":"32"}},{"t":"case","label":"United States v. Jin Fuey Moy","cite":"241 U.S. 394","y":1916,"id":"scdb/1915-167","sc":1,"sum":"A statute must be so construed, if fairly possible, as to avoid not only the conclusion that it is unconstitutional, but also grave doubts upon that score. United States v. Delaware & Hudson Co., 213 TJ. S. 366.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"28, 45"}},{"t":"case","label":"United States v. Ojeda Rios","cite":"846 F.2d 167","y":1988,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/846/167/","by":{"1":"32"}},{"t":"case","label":"United States v. Salerno","cite":"481 U.S. 739","y":1987,"id":"1986/86-87","sc":1,"sum":"The Court held that the Act was constitutional because when the government's interest in protecting the community outweighs individual liberty, pre-trial detention can be \"a potential solution to a pressing societal problem.\" The Act only applied to a specific list of serious offenses, placed heavy burdens on the government to prove that the arrestee posed significant threats to others, and did not prevent the accused from enjoying a speedy trial.","sumSrc":"Oyez","by":{"1":"32, 33, 39, 42"}},{"t":"case","label":"United States v. Wilson","cite":"503 U.S. 329","y":1992,"id":"1991/90-1745","sc":1,"sum":"It is the Attorney General who computes the amount of the § 3585(b) credit after the defendant has begun to serve his sentence.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"58"}},{"t":"case","label":"United States v. Wong Kim Ark","cite":"169 U.S. 649","y":1898,"id":"1850-1900/169us649","sc":1,"sum":"Because Wong was born in the United States and his parents were not “employed in any diplomatic or official capacity under the Emperor of China,” the Citizenship Clause of the Fourteenth Amendment automatically makes him a U.S. citizen.","sumSrc":"Oyez","by":{"1":"30"}},{"t":"case","label":"Yee v. City of Escondido","cite":"503 U.S. 519","y":1992,"id":"1991/90-1947","sc":1,"sum":"The Fifth Amendment's Takings Clause generally requires just compensation where the government authorizes a physical occupation of property. But where the government merely regulates the property's use, compensation is required only if considerations such as the regulation's purpose or the extent to which it deprives the owner of the property's economic use suggests that the regulation has unfairly singled out the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"49"}},{"t":"usc","label":"8 U.S.C. § 1221","url":"https://www.law.cornell.edu/uscode/text/8/1221","stext":{"head":"§1221. Lists of alien and citizen passengers arriving and departing","paras":[[0,"(a) Arrival manifests"],[0,"For each commercial vessel or aircraft transporting any person to any seaport or airport of the United States from any place outside the United States, it shall be the duty of an appropriate official specified in subsection (d) to provide to any United States border officer (as defined in subsection (i)) at that port manifest information about each passenger, crew member, and other occupant transported on such vessel or aircraft prior to arrival at that port."],[0,"(b) Departure manifests"],[0,"For each commercial vessel or aircraft taking passengers on board at any seaport or airport of the United States, who are destined to any place outside the United States, it shall be the duty of an appropriate official specified in subsection (d) to provide any United States border officer (as defined in subsection (i)) before departure from such port manifest information about each passenger, crew member, and other occupant to be transported."],[0,"(c) Contents of manifest"],[0,"The information to be provided with respect to each person listed on a manifest required to be provided under subsection (a) or (b) shall include—"],[1,"(1) complete name;"],[1,"(2) date of birth;"],[1,"(3) citizenship;"],[1,"(4) sex;"],[1,"(5) passport number and country of issuance;"],[1,"(6) country of residence;"],[1,"(7) United States visa number, date, and place of issuance, where applicable;"],[1,"(8) alien registration number, where applicable;"],[1,"(9) United States address while in the United States; and"],[1,"(10) such other information the Attorney General, in consultation with the Secretary of State, and the Secretary of Treasury determines as being necessary for the identification of the persons transported and for the enforcement of the immigration laws and to protect safety and national security."],[0,"(d) Appropriate officials specified"],[0,"An appropriate official specified in this subsection is the master or commanding officer, or authorized agent, owner, or consignee, of the commercial vessel or aircraft concerned."],[0,"(e) Deadline for requirement of electronic transmission of manifest information"],[0,"Not later than January 1, 2003, manifest information required to be provided under subsection (a) or (b) shall be transmitted electronically by the appropriate official specified in subsection (d) to an immigration officer."],[0,"(f) Prohibition"],[0,"No operator of any private or public carrier that is under a duty to provide manifest information under this section shall be granted clearance papers until the appropriate official specified in subsection (d) has complied with the requirements of this subsection, except that, in the case of commercial vessels or aircraft that the Attorney General determines are making regular trips to the United States, the Attorney General may, when expedient, arrange for the provision of manifest information of persons departing the United States at a later date."],[0,"(g) Penalties against noncomplying shipments, aircraft, or carriers"],[0,"If it shall appear to the satisfaction of the Attorney General that an appropriate official specified in subsection (d), any public or private carrier, or the agent of any transportation line, as the case may be, has refused or failed to provide manifest information required by subsection (a) or (b), or that the manifest information provided is not accurate and full based on information provided to the carrier, such official, carrier, or agent, as the case may be, shall pay to the Commissioner the sum of $1,000 for each person with respect to whom such accurate and full manifest information is not provided, or with respect to whom the manifest information is not prepared as prescribed by this section or by regulations issued pursuant thereto. No commercial vessel or aircraft shall be granted clearance pending determination of the question of the liability to the payment of such penalty, or while it remains unpaid, and no such penalty shall be remitted or refunded, except that clearance may be granted prior to the determination of such question upon the deposit with the Commissioner of a bond or undertaking approved by the Attorney General or a sum sufficient to cover such penalty."],[0,"(h) Waiver"],[0,"The Attorney General may waive the requirements of subsection (a) or (b) upon such circumstances and conditions as the Attorney General may by regulation prescribe."],[0,"(i) United States border officer defined"],[0,"In this section, the term \"United States border officer\" means, with respect to a particular port of entry into the United States, any United States official who is performing duties at that port of entry."],[0,"(j) Record of citizens and resident aliens leaving permanently for foreign countries"],[0,"The Attorney General may authorize immigration officers to record the following information regarding every resident person leaving the United States by way of the Canadian or Mexican borders for permanent residence in a foreign country: Names, age, and sex; whether married or single; calling or occupation; whether able to read or write; nationality; country of birth; country of which citizen or subject; race; last permanent residence in the United States; intended future permanent residence; and time and port of last arrival in the United States; and if a United States citizen or national, the facts on which claim to that status is based."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1221?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§1221. Lists of alien and citizen passengers arriving and departing","tname":"Aliens and Nationality","by":{"1":"49, 52"}},{"t":"usc","label":"8 U.S.C. § 1252c","url":"https://www.law.cornell.edu/uscode/text/8/1252c","subs":["(a)"],"by":{"1":"59"}},{"t":"usc","label":"8 U.S.C. § 1601","url":"https://www.law.cornell.edu/uscode/text/8/1601","subs":["(4)"],"stext":{"head":"§1601. Statements of national policy concerning welfare and immigration","paras":[[0,"The Congress makes the following statements concerning national policy with respect to welfare and immigration:"],[1,"(1) Self-sufficiency has been a basic principle of United States immigration law since this country's earliest immigration statutes."],[1,"(2) It continues to be the immigration policy of the United States that—"],[2,"(A) aliens within the Nation's borders not depend on public resources to meet their needs, but rather rely on their own capabilities and the resources of their families, their sponsors, and private organizations, and"],[2,"(B) the availability of public benefits not constitute an incentive for immigration to the United States."],[1,"(3) Despite the principle of self-sufficiency, aliens have been applying for and receiving public benefits from Federal, State, and local governments at increasing rates."],[1,"(4) Current eligibility rules for public assistance and unenforceable financial support agreements have proved wholly incapable of assuring that individual aliens not burden the public benefits system."],[1,"(5) It is a compelling government interest to enact new rules for eligibility and sponsorship agreements in order to assure that aliens be self-reliant in accordance with national immigration policy."],[1,"(6) It is a compelling government interest to remove the incentive for illegal immigration provided by the availability of public benefits."],[1,"(7) With respect to the State authority to make determinations concerning the eligibility of qualified aliens for public benefits in this chapter, a State that chooses to follow the Federal classification in determining the eligibility of such aliens for public assistance shall be considered to have chosen the least restrictive means available for achieving the compelling governmental interest of assuring that aliens be self-reliant in accordance with national immigration policy."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1601?type=usc&year=mostrecent&link-type=html"},"head":"§1601. Statements of national policy concerning welfare and immigration","tname":"Aliens and Nationality","by":{"1":"58","2":"10"}},{"t":"usc","label":"8 U.S.C. § 1738","url":"https://www.law.cornell.edu/uscode/text/8/1738","by":{"1":"59"}},{"t":"reg","label":"8 C.F.R. § 208.16","url":"https://www.ecfr.gov/current/title-8/section-208.16","subs":["(c)(2)","(f)(2)"],"by":{"1":"5, 6"}},{"t":"reg","label":"8 C.F.R. § 208.31","url":"https://www.ecfr.gov/current/title-8/section-208.31","subs":["(e)"],"by":{"1":"5, 11"}},{"t":"reg","label":"8 C.F.R. § 214.13","url":"https://www.ecfr.gov/current/title-8/section-214.13","subs":["(b)(2)"],"by":{"1":"10"}},{"t":"reg","label":"8 C.F.R. § 241.14","url":"https://www.ecfr.gov/current/title-8/section-241.14","subs":["(a)","(g)","(i)(1)","(f)","(g)(3)","(i)(4)"],"by":{"1":"10, 10, 10, 16, 25, 3, 16, 25, 26, 10, 10"}},{"t":"reg","label":"8 C.F.R. § 241.4","url":"https://www.ecfr.gov/current/title-8/section-241.4","subs":["(i)(1)","(i)(3)","(i)(3)(i)","(c)(1)","(c)(2)","(d)","(d)(1)","(h)(1)","(h)(5)","(k)(2)","(k)(2)(iii)"],"by":{"1":"8, 9, 8, 8, 8, 8, 8, 44, 9, 44, 8, 8, 8, 37"}},{"t":"reg","label":"8 C.F.R. § 241.5","url":"https://www.ecfr.gov/current/title-8/section-241.5","subs":["(a)","(b)"],"by":{"1":"8, 8, 24"}},{"t":"reg","label":"8 C.F.R. § 241.8","url":"https://www.ecfr.gov/current/title-8/section-241.8","subs":["(a)","(e)"],"by":{"1":"4, 4"}},{"t":"reg","label":"8 C.F.R. § 241.13","url":"https://www.ecfr.gov/current/title-8/section-241.13","subs":["(b)(2)","(e)(5)","(g)(1)"],"by":{"1":"8, 9, 16, 25, 8, 9"}},{"t":"reg","label":"8 C.F.R. § 1208.16","url":"https://www.ecfr.gov/current/title-8/section-1208.16","subs":["(e)"],"by":{"1":"5"}},{"t":"reg","label":"8 C.F.R. § 1208.31","url":"https://www.ecfr.gov/current/title-8/section-1208.31","subs":["(e)"],"by":{"1":"6"}},{"t":"reg","label":"8 C.F.R. § 1236.1","url":"https://www.ecfr.gov/current/title-8/section-1236.1","subs":["(d)(1)"],"by":{"1":"23"}},{"t":"reg","label":"Other Authorities, 34 Fed. Reg. 8037","url":"https://www.govinfo.gov/link/fr/34/8037","by":{"1":"23"}},{"t":"reg","label":"38 Fed. Reg. 8590","url":"https://www.govinfo.gov/link/fr/38/8590","by":{"1":"23"}},{"t":"reg","label":"48 Fed. Reg. 8038","url":"https://www.govinfo.gov/link/fr/48/8038","by":{"1":"23"}},{"t":"reg","label":"64 Fed. Reg. 8478","url":"https://www.govinfo.gov/link/fr/64/8478","by":{"1":"5"}},{"t":"reg","label":"66 Fed. Reg. 56967","url":"https://www.govinfo.gov/link/fr/66/56967","by":{"1":"9, 25"}},{"t":"const","label":"Amendment VIII","clauses":[["eighth-amendment","Eighth Amendment"]],"text":"Excessive bail shall not be required, nor excessive fines imposed, nor cruel and unusual punishments inflicted.","by":{"1":"30, 32"}},{"t":"case","label":"Armstrong v. Exceptional Child Center, Inc.","cite":"575 U.S. 320","y":2015,"id":"2014/14-15","sc":1,"sum":"A case that determines whether or not a private right of action exists under the Medicaid Act.","sumSrc":"Oyez","by":{"2":"7"}},{"t":"case","label":"Catholic Social Services, Inc. v. INS","cite":"232 F.3d 1139","y":2000,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/232/1139/","by":{"2":"5"}},{"t":"case","label":"Facebook, Inc. v. Duguid","cite":"141 S. Ct. 1163","y":2021,"id":"2020/18-956","sc":1,"sum":"Google’s limited copying of the Java SE Application Programming Interface allowed programmers to put their accrued talents to work in a transformative program and constituted a fair use of that material under copyright law.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"4"}},{"t":"case","label":"FTC v. Cement Institute","cite":"333 U.S. 683","y":1948,"id":"scdb/1947-067","sc":1,"sum":"L The Commission has jurisdiction to conclude that conduct tending to restrain trade is an unfair method of competition viola-tive of § 5 of the Federal Trade Commission Act, even though the selfsame conduct may also violate the Sherman Act. Pp. 689-693. Cement Co. et al.; No. 25, Federal Trade Comm'n v. Marquette Cement Mig. Co.; No. 26, Federal Trade Comm'n v. Calaveras Cement Co. et al..N;o. 27, Federal Trade …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"22"}},{"t":"case","label":"Goss v. Lopez","cite":"419 U.S. 565","y":1975,"id":"1974/73-898","sc":1,"sum":"The Court ruled that Ohio violated students' Due Process rights guaranteed by the First Amendment when it imposed suspensions without preliminary hearings.","sumSrc":"Oyez","by":{"2":"23"}},{"t":"case","label":"(III) Cases—Continued: Harris Trust & Savings Bank v. Salomon Smith Barney Inc.","cite":"530 U.S. 238","y":2000,"id":"1999/99-579","sc":1,"sum":"The Court held that Section 502(a)(3)'s authorization to a plan \"participant, beneficiary, or fiduciary\" to bring a civil action for \"appropriate equitable relief\" extends to a suit against a nonfiduciary \"party in interest\" to a prohibited transaction barred by section 406(a). \"We reject,\" wrote Justice Thomas that, \"absent a substantive provision of ERISA expressly imposing a duty upon a nonfiduciary party in interest, the nonfiduciary party may not be held liable under [section 502(a)(3)].\" Justice Thomas concluded that \"[section 502(a)(3)] itself imposes certain duties, and therefore that liability under that provision does not depend on whether ERISA's substantive provisions impose a specific duty on the party being sued.\".","sumSrc":"Oyez","by":{"2":"16"}},{"t":"case","label":"Henderson v. Shinseki","cite":"562 U.S. 428","y":2011,"id":"2010/09-1036","sc":1,"sum":"The Court held that missing the deadline for filing a notice of appeal with the Veterans Court did not bar a plaintiff from making a claim.","sumSrc":"Oyez","by":{"2":"2"}},{"t":"case","label":"Johnson v. United States","cite":"333 U.S. 10","y":1948,"id":"scdb/1947-031","sc":1,"by":{"2":"22"}},{"t":"case","label":"Marcello v. Bonds","cite":"349 U.S. 302","y":1955,"id":"scdb/1954-086","sc":1,"ar":1,"sum":"After a hearing pursuant to § 242 (b) of the Immigration and Nationality Act of 1952, petitioner, an alien who had been convicted in 1938 of violation of the Marihuana Tax Act, was ordered deported. Section 241 (a) (11) of the 1952 Act makes such conviction at any time ground for deportation, and § 241 (d) provides that the deportation prdvisions of § 241 (a) shall apply even though the facts giving rise to the …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"22"}},{"t":"case","label":"Morrissey v. Brewer","cite":"408 U.S. 471","y":1972,"id":"1971/71-5103","sc":1,"sum":"The Court held that due process required Iowa to include a preliminary hearing to determine probable cause for the parole revocations of Morrissey and Booker.","sumSrc":"Oyez","by":{"2":"23"}},{"t":"case","label":"Moskal v. United States","cite":"498 U.S. 103","y":1990,"id":"1990/89-964","sc":1,"sum":"A person who receives genuine vehicle titles, knowing that they incorporate fraudulently tendered odometer readings, receives those titles knowing them to have been \"falsely made\" in violation of § 2314.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"4"}},{"t":"case","label":"Opati v. Republic of Sudan","cite":"140 S. Ct. 1601","y":2020,"id":"2019/17-1268","sc":1,"sum":"The Court held that the Foreign Sovereign Immunities Act (FSIA) applies retroactively, thereby permitting recovery of punitive damages against foreign states for terrorist activities occurring prior to the passage of the current version of the statute.","sumSrc":"Oyez","by":{"2":"13"}},{"t":"case","label":"Sosna v. Iowa","cite":"419 U.S. 393","y":1975,"id":"1974/73-762","sc":1,"sum":"Appellant's petition for divorce was dismissed by an Iowa trial court for lack of jurisdiction because she failed to meet the Iowa statutory requirement that a petitioner in a divorce action be a resident of the State for one year preceding the filing of the petition. Appellant then brought a class action under Fed. Rule Civ. Proc. 23 in the Federal District Court against appellees State and state trial judge, …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"12"}},{"t":"case","label":"United States v. Chemical Foundation, Inc.","cite":"272 U.S. 1","y":1926,"id":"scdb/1926-001","sc":1,"sum":"1. A decree of the Circuit Court of Appeals, entered prior to the taking effect of the Jurisdictional Act of February 13, 1925, and affirming dismissal on the merits of a bill by the United States to set aside, as unauthorized and fraudulently procured, sales of patent and other rights and properties seized pursuant to the Trading, with the Enemy Act, was reviewable by this Court on appeal (Jud. Code §§ 128, 241). …","sumSrc":"Headnote (U.S. Reports)","by":{"2":"22"}},{"t":"case","label":"United States v. Cotton","cite":"535 U.S. 625","y":2002,"id":"2001/01-687","sc":1,"sum":"The Court held that the omission from a federal indictment of a fact that enhances the statutory maximum sentence does not justify a Court of Appeals' vacating the enhanced sentence, even though the defendant did not object in the trial court.","sumSrc":"Oyez","by":{"2":"2"}},{"t":"usc","label":"8 U.S.C. § 1182","url":"https://www.law.cornell.edu/uscode/text/8/1182","subs":["(a)(6)(A)(i)","(a)(9)(A)(ii)(I)"],"by":{"2":"15, 15"}},{"t":"usc","label":"8 U.S.C. § 1446","url":"https://www.law.cornell.edu/uscode/text/8/1446","subs":["(a)"],"by":{"2":"10"}},{"t":"usc","label":"8 U.S.C. § 1522","url":"https://www.law.cornell.edu/uscode/text/8/1522","subs":["(a)(7)(B)"],"by":{"2":"4"}},{"t":"reg","label":"Detention of Aliens Ordered Removed, 65 Fed. Reg. 80,281","url":"https://www.govinfo.gov/link/fr/65/80281","by":{"2":"17"}}]};